		add(3+i-1, 3+i-1, 3+i);
		//cout << a[3+i] << endl;
	}
	for(int i=A-1; ~i; --i) {
		add(33, 3+i, 34);
		//a[34] <= a[0]
		cmp(0, 34, 35);
		//a[35] should be 0 if add
		cmp(35, 3, 36);
		//a[36] should be 1 if add
		add(36, 6969, 37);
		//update a so far
		for(int k=0; k<i; ++k)
			add(37, 37, 37);
		add(33, 37, 33);
		//need a[<=33], a[36]
		//used up to 37
