    /* specify A */
    for(int i = 29; i >= 0; i--){
        cout << "+ 5 " << 100 + i << " 6" << endl;  // a[5] = now A, a[6] = new A

        /* ith bit */
        cout << "< 6 3 " << 200 + i << endl;    // new A < A + 1 <=> ith bit stand

        /* a[7] = 2 ^ i or 0 */
        cout << "+ 99 " << 200 + i << " 7" << endl;
        for(int j = 0; j < i; j++){
            cout << "+ 7 7 7" << endl;
        }

        cout << "+ 5 7 5" << endl;  // renew A
    }

    cout << "< 0 0 5" << endl;  // a[5] = 0

    /* calc A * B */
    for(int i = 29; i >= 0; i--){
        cout << "+ 5 " << 100 + i << " 6" << endl;  // a[5] = now B, a[6] = new B

        /* ith bit */
        cout << "< 6 4 " << 300 + i << endl;    // new B < B + 1 <=> ith bit stand

        for(int j = 0; j < 30; j++){
            /* (flag (A & 2 ^ j)) & (flag (B & 2 ^ i)) */
            cout << "+ " << 300 + i << " " << 200 + j << " 8" << endl;
            cout << "< 100 8 7" << endl;

            for(int k = 0; k < i + j; k++){
                cout << "+ 7 7 7" << endl;
            }

            cout << "+ 2 7 2" << endl;
        }

        /* a[7] = 2 ^ i or 0 */
        cout << "+ 99 " << 300 + i << " 7" << endl;
        for(int j = 0; j < i; j++){
            cout << "+ 7 7 7" << endl;
        }

        cout << "+ 5 7 5" << endl;  // renew B
    }
}

