// TEST A = 0, B = 0
void solve() {
  //cin >> a[0] >> a[1];

  int A = getIt();
  int B = getIt();
  int res = getIt();

  int zero = getIt();
  // Create one. NOTE: Does not work with A=B=0
  int tmp = getIt();
  int one = getIt();
  add(tmp, A, B);
  add(tmp, tmp, A);
  add(tmp, tmp, B);

  dout << dvar(tmp) << endl;
  cmp(one, A, tmp);

  int multOfBCnt = getIt();
  int multOfB = getIt();
  int toAdd = getIt(); // 1*B = B, 0*B = 0
  int copyB = getIt(); 
  int flag1 = getIt();
  int flag2 = getIt();
  int cnt = getIt();

  F0R(_, 10) {


    cmp(toAdd, cnt, A);

    // a && b:
    //   1 < (a + b)

    // a >= b:
    //   b < (a + 1)


    // add 'toAdd' to 'copyB' 'A' times
    add(copyB, zero, zero);
    F0R(i, 10) {
      cmp(flag1, copyB, B);
      cmp(flag2, cnt, A);
      add(flag1, flag1, flag2);
      cmp(toAdd, one, flag1);
      // toAdd = copyB<B && cnt<A

      add(copyB, copyB, toAdd);
    }

    add(res, res, copyB);
    add(cnt, cnt, one);
  }
  //cout << a[2] << endl;
}

