//4: 0, 5: 1, 6: 2, ..., 14: 10

struct Node
{
	char op;
	int a, b, c;
	Node(char C = 0, int X = 0, int Y = 0, int Z = 0) { op = C; a = X; b = Y; c = Z; }
};

int v[105];

vector<Node> ans;

inline void add(int a, int b, int c) { ans.push_back( Node('+', a, b, c) ); v[c] = v[a] + v[b]; }

inline void cmp(int a, int b, int c) { ans.push_back( Node('<', a, b, c) ); v[c] = (v[a] < v[b]); }

int main()
{
	add(0, 1, 3); cmp(5, 3, 5);
	for(int i = 6; i <= 14; i++) add(5, i - 1, i);
	int a = 15, b = 25;
	for(int i = a; i <= a + 9; i++) cmp(0, i - 10, i);
	for(int i = b; i <= b + 9; i++) cmp(i - 21, 1, i);
	for(int i = a; i <= a + 9; i++)
		for(int j = b; j <= b + 9; j++)
		{
			cmp(i, j, 100);
			add(2, 100, 2);
		}
	printf("%lu\n", ans.size());
	for(int i = 0; i < ans.size(); i++) printf("%c %d %d %d\n", ans[i].op, ans[i].a, ans[i].b, ans[i].c);
	return 0;
}

