int pnt = 3;

int op(int type, int i, int j) {
	if (!type) {
		cout << "+ ";
	} else {
		cout << "< ";
	}
	cout << i << ' ' << j << ' ' << pnt << '\n';
	pnt++;
	return pnt - 1;
}

signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int some_bigger = op(0, 0, 1);
	some_bigger = op(0, some_bigger, some_bigger);
	int ONE = op(1, 0, some_bigger);
	vector<int> pointers;
	pointers.push_back(op(0, pnt, pnt));
	pointers.push_back(ONE);
	for (int i = 2; i <= 10; i++) {
		pointers.push_back(op(0, pointers[i - 1], ONE));
	}
	vector<int> pa(11);
	for (int i = 0; i <= 10; i++) {
		pa[i] = op(1, pointers[i], 0);
	}
	vector<int> pb(11);
	for (int i = 0; i <= 10; i++) {
		pb[i] = op(1, pointers[i], 1);
	}
	vector<int> to_sum;
	for (int i = 0; i <= 10; i++) {
		for (int j = 0; j <= 10; j++) {
			int sm = op(0, pa[i], pb[j]);
			int is_2 = op(1, ONE, sm);
			to_sum.push_back(is_2);
		}
	}
	for (auto i : to_sum) {
		cout << "+ " << 2 << ' ' << i << ' ' << 2 << '\n';
	}

}

