const int n = (int) 2e5;
const int zero = n - 1;
const int maxb = 30;
int curc;
vector<pair<pair<char, int>, pair<int, int>>> ans;

void addOp(char op, int i, int j, int k) {
  ans.push_back(make_pair(make_pair(op, i), make_pair(j, k)));
}

int getAnd(int a, int b) {
  int sum = curc++;
  addOp('+', a, b, sum);
  int sum1 = curc++;
  addOp('<', zero, sum, sum1);
  int sum2 = curc++;
  addOp('<', sum1, sum, sum2);
  return sum2;
}

int getNot(int a, int b) {
  int res = curc++;
  addOp('<', a, b, res);
  return res;
}

void getPow(int a, int p) {
  for (int i = 0; i < p; ++i) {
    addOp('+', a, a, a);
  }
}

void getBit(int a, int c, int b, int bit) {
  int p = curc++;
  addOp('<', zero, a, p);
  getPow(p, bit);
  int nc = curc++;
  addOp('+', c, p, nc);
  int cmp = curc++;
  addOp('<', a, nc, cmp);
  int q = curc++;
  addOp('<', zero, a, q);
  int x = getNot(cmp, q);
  addOp('+', x, zero, b);
  getPow(x, bit);
  addOp('+', c, x, c);
}

void solve() {
  ans.clear();
  int a = 0, b = 1, res = 2;
  curc = 3;
  int ac = curc++;
  for (int i = maxb; i >= 0; --i) {
    int ba = curc++;
    getBit(a, ac, ba, i);
    int bc = curc++;
    for (int j = maxb; j >= 0; --j) {
      int bb = curc++;
      getBit(b, bc, bb, j);
      int x = getAnd(ba, bb);
      getPow(x, i + j);
    }
  }
  printf("%d\n", sz(ans));
  for (int i = 0; i < sz(ans); ++i) {
    printf("%c %d %d %d\n", ans[i].first.first, ans[i].first.second, ans[i].second.first, ans[i].second.second);
  }
}

