const int t=29;
const int N=200000;

vector<PP> ret;

void pp(int i,int j,int k){
	ret.push_back(PP(P(0,i),P(j,k)));
	//printf("+ %d %d %d\n",i,j,k);
}
void po(int i,int j,int k){
	ret.push_back(PP(P(1,i),P(j,k)));
	//printf("< %d %d %d\n",i,j,k);
}

void make_power(){
	po(N-1,0,N-2);
	for(int i=1;i<=t;i++){
		pp(N-2-i+1,N-2-i+1,N-2-i);
	}
	po(N-1,1,N-50);
}
void POW(int k,int s){
	for(int i=0;i<s;i++){
		pp(k,k,k);
	}
}

int x_times_B(int k){ //x=0,1
	po(k,N-50,N-51);
	for(int i=1;i<=t;i++){
		pp(k+i-1,k+i-1,k+i);
	}
	for(int i=t;i>=0;i--){
		pp(k+t+3,k+i,k+t+2);
		po(k+t+2,1,k+t+1);
		po(N-51,k+t+1,k+t+1);
		POW(k+t+1,i);
		pp(k+t+3,k+t+1,k+t+3);
		//pp(k+t+3,N-1,k+t+2);
	}
	po(N-51,N-50,N-51);
	pp(k+t+3,N-51,k+t+3);
	return k+t+3;
}

void solve(){
	int x=3,y=4;
	int nex=5;
	for(int i=t;i>=0;i--){
		pp(x,N-2-i,nex);
		po(nex,0,nex+1);
		pp(nex+1,N-1,nex+2);
		POW(nex+1,i);
		pp(x,nex+1,x);
		int z=x_times_B(nex+2);
		POW(z,i);
		pp(y,z,y);
		nex=z+1;
	}
	pp(N-2,N-1,nex);
	int z=x_times_B(nex);
	pp(y,z,2);
}

