  cnt = 4;
  pw2[0] = cnt;
  for (int i = 1; i <= 30; i++) {
    pw2[i] = ++cnt;
    add(pw2[i-1], pw2[i-1], pw2[i]);
  }
}

void shift(int i, int it) {
  add(i, cnt+1, cnt+1); ++cnt;
  for (int j = 1; j <= it; j++) {
    add(cnt, cnt, cnt+1); ++cnt;
  }
}

