vector<int> find_bin(int i) {
  vector<int> ret(31, 0);
  int lst = ++cnt;
  add(i, pw2[0], lst); i = lst;
  // check.push_back(lst);
  lst = ++cnt;
  for (int it = 30; it >= 0; it--) {
    add(lst, pw2[it], ++cnt); // lst + (1 << it)
    comp(cnt, i, cnt+1); // lst + (1 << it) < i
    ret[it] = ++cnt;
    shift(ret[it], it);
    add(lst, cnt, cnt+1); // lst += 1 << it
    lst = ++cnt;
  }
  return ret;
}

void mul(int i, int j) {
  comp(i, pw2[0], ++cnt);
  comp(cnt, j, cnt+1); ++cnt;
}

