using namespace std;


struct cmd_t
{
	int act, i, j, k;
	bool operator==(const cmd_t&rhs)
	{
		if(act!=rhs.act) return false;
		if(i!=rhs.i) return false;
		if(j!=rhs.j) return false;
		if(k!=rhs.k) return false;
		return true;
	}
};

vector<cmd_t> ans;
void cmd(int act, int i, int j, int k)
{
	ans.push_back(cmd_t{act, i, j, k});
}

enum{
	A=0,
	B,
	ANS,
	ZERO,
	ONE,
	T,
	X,
	BEKI2=100,
	BEKI2_=200,
	CHK_B_B=300,
	SHIFT_A=400,
	BIN_B=500,
	WORK1=1000,
	WORK2=2000,
};

int beki2(int bit)
{
	return BEKI2+bit;
}

int beki2_(int bit)
{
	return BEKI2_+bit;
}


int chk_b_bit(int bit)
{
	return CHK_B_B+bit;
}


void value_divide(int v, int t, int work)
{
	int tmp=work+70;
	int is_bit_used=work+71;

	for(int i=0;i<=60;i++) cmd('+', ZERO, beki2_(i), work+i);
	for(int i=60;i>=0;i--)
	{
		cmd('<', work+i, v, is_bit_used);
		cmd('+', ZERO, is_bit_used, t+i);
		cmd('+', ZERO, is_bit_used, tmp);
		for(int j=0;j<i;j++) cmd('+', tmp, tmp, tmp);
		for(int j=i;j>=0;j--)
		{
			cmd('+', work+j, tmp, work+j);
		}
	}
}


void if_x_v_t(int x, int v, int t, int work1, int work2)
{
	cmd('+', ZERO, ZERO, t);

	value_divide(v, work1, work2);
	for(int i=0;i<=60;i++)
	{
		cmd('<', ZERO, work1+i, T);
		for(int j=0;j<i;j++)
		{
			cmd('+', T, T, T);
		}
		cmd('+', t, T, t);
	}
}


