{
	cmd('<', ZERO, A, ONE);
	// a[100]-[129] 1 2 4 8 ... 2^29
	// a[200]-[229] 0 1 3 7 ... 2^29-1
	cmd('+', ZERO, ONE, beki2(0));
	for(int i=1;i<=60;i++)
	{
		cmd('+', beki2(i-1), beki2(i-1), beki2(i));
		cmd('+', beki2_(i-1), beki2(i-1), beki2_(i));
	}
	cmd('+', ZERO, A, SHIFT_A);
	for(int i=1;i<=30;i++)
	{
		cmd('+', i-1+SHIFT_A, i-1+SHIFT_A, i+SHIFT_A);
	}
	value_divide(B, BIN_B, WORK1);

	for(int i=30;i>=0;i--)
	{
		if_x_v_t(BIN_B+i, SHIFT_A+i, T, WORK1, WORK2);
		cmd('+', ANS, T, ANS);
	}

	int n=ans.size();
	printf("%d\n", n);
if(1)
{
