vector < int > decomp(int u){
	int i,j,k;
	vector < int > pws(31);
	for(i=0;i<=30;++i) pws[i]=ptr++;
	ass(one,pws[0]);
	for(i=1;i<=30;++i){
		add(pws[i-1],pws[i-1],pws[i]);
	}
	vector < int > ret(31);
	for(i=0;i<=30;++i) ret[i]=ptr++;
	int got=ptr++;
	for(i=30;i>=0;--i){
		int cur=ptr++;
		for(j=0;j<i;++j) add(cur,pws[j],cur);
		add(cur,got,cur);
		int cmpv=ptr++;
		cmp(cur,u,cmpv);
		ass(ret[i],cmpv);
		left_shift_by_k(cmpv,i);
		add(got,cmpv,got);
	}
	return ret;
}
