{
    // A[i] <- 0
    compare(i, i, i);
}

void copy(int i, int j)
{
    if (i == j) return;
    reset(j);
    add(i, j, j);
}

// 300番台使用
void multiply(int i, int j, lint X)
{
    // A[j] = A[i] * X
    copy(i, 300);
    REP(d, 60)
    {
        add(300 + d, 300 + d, 300 + d + 1);
        if (1LL << d > X) break;
    }

    reset(j);
    REP(d, 60) if ((X >> d) & 1) add(300 + d, j, j);
}


// 100番台使用
void subtract(int i, int j, int ret)
{
    // A[k] <- A[i] - A[j]
    int tmp = 90, cum = 91;
    reset(cum);
    IREP(d, 32)
    {
        add(cum, j, tmp);
        add(tmp, 100 + d, tmp);
        compare(tmp, i, 92);
        multiply(92, 92, 1LL << d);
        add(92, cum, cum);
    }
    copy(cum, ret);
}

