			ost << "+ " << p.i << ' ' << p.j << ' ' << p.k << endl;
		} else {
			ost << "< " << p.i << ' ' << p.j << ' ' << p.k << endl;
		}
	}
}

void pls(int i, int j, int k) {
	ans.push_back(Query{ 0, i, j, k });
}

void comp(int i, int j, int k) {
	ans.push_back(Query{ 1, i, j, k });
}

void pre() {
	pls(0, 1, MAX_N - 1);
}

void one(int pos) {
	comp(MAX_N - 2, MAX_N - 1, pos);
}

void zero(int pos) {
	comp(pos, pos, pos);
}

void pw(int tar, int k) {
	REP(z, 0, k) {
		pls(tar, tar, tar);
	}
}

void bin(int tar, int pos, int mem) {
	int copied = mem;
	int sum = mem + 1;
	int tmp = mem + 2;
	int res = mem + 3;
	one(copied);
	pls(copied, tar, copied);
	REM(k, 0, bits) {
		one(tmp);
		pw(tmp, k);
		pls(tmp, sum, tmp);
		comp(tmp, copied, res);
		comp(tmp, copied, pos + k);
		pw(res, k);
		pls(sum, res, sum);
		zero(tmp);
		zero(res);
	}
	zero(sum);
	zero(tmp);
	zero(res);
	zero(copied);
}

