	one(d);
	REP(i, 0, bits) {
		REP(j, 0, bits) {
			int pos = c + i * bits + j;
			pls(a + i, b + j, pos);
			comp(d, pos, pos);
			pw(pos, i + j);
			pls(2, pos, 2);
		}
	}

	out(cout);
	return 0;
}

