    };
    const auto& add = [](unsigned long i, unsigned long j, unsigned long k) -> void {
        cout << "+ " << i << " " << j << " " << k << endl;
    };
    const auto& set_one = [&cmp, &add]() -> void {
        add(0, 1, one_reg);
        cmp(2, one_reg, one_reg);
    };
    const auto& bit_and_add = [&cmp, &add](unsigned long i, unsigned long j, unsigned long k) -> void {
        add(i, j, reg);
        cmp(one_reg, reg, reg + 1);
        add(k, reg + 1, k);
    };
    const auto& binary_mul = [&add, &bit_and_add](unsigned long i, unsigned long i_len, unsigned long j, unsigned long j_len, unsigned long k) -> void {
        for(unsigned long itr{0}; itr < i_len + j_len - 1; ++itr){
            if(itr)add(k, k, k);
            for(unsigned long jtr{0}; jtr <= itr; ++jtr)if(jtr < j_len && jtr + i_len > itr)bit_and_add(i + itr - jtr, j + jtr, k);
        }
    };
    const auto& int_to_bin = [&cmp, &add](unsigned long idx, unsigned long i, unsigned long len, unsigned long j) -> void {
        for(unsigned long itr{0}; itr < len; ++itr){
            if(itr)add(j + itr - 1, j + itr - 1, j + itr);
            add(j + itr, one_reg, j + itr);
            for(unsigned long jtr{itr}; jtr + 1 < len; ++jtr)add(j + jtr, j + jtr, j + jtr + 1);
            cmp(j + len - 1, idx, i + itr);
            add(j + itr - 1, j + itr - 1, j + itr);
            add(j + itr, i + itr, j + itr);
        }
    };

