		Op.push_back('<');
		In1.push_back(id_);
		In2.push_back(b.id_);
		Out.push_back(last_id);
		return V(last_id++);
	}
	inline V operator>(const V& b) const {
		return b < *this;
	}
	int id_;
};

V pows[60], bpow[30];
V a(0), b(1), zero(2);

V mulpow2(V x, int n) {
	V ret = x;
	for (int i = 0; i < n; ++i) ret = ret + ret;
	return ret;
}

V cond(V x, V y, int rep) {
	// x ? y : 0
	// y < 2 ** rep
	V negx = x < pows[0];
	V ret = zero;
	for (int i = rep - 1; i >= 0; --i) {
		V c = y > (ret + pows[i]);
		c = c > negx;
		ret = ret + mulpow2(c, i);
	}
	return ret + ((y > zero) > negx);
}

typedef unsigned long long ui64;

ui64 emulate(ui64 x, ui64 y) {
	const int maxn = 200000;
	const ui64 maxv = 10000000000000000000ULL;
	vector<ui64> buffer(maxn, 0LL);
	buffer[0] = x;
	buffer[1] = y;
	for (int i = 0; i < Op.size(); ++i) {
		if (!(0 <= In1[i] && In1[i] < maxn)) abort();
		if (!(0 <= In2[i] && In2[i] < maxn)) abort();
		if (!(0 <= Out[i] && Out[i] < maxn)) abort();

		if (Op[i] == '+') {
			buffer[Out[i]] = buffer[In1[i]] + buffer[In2[i]];
			if (buffer[Out[i]] > maxv) abort();
		} else {
			buffer[Out[i]] = (buffer[In1[i]] < buffer[In2[i]]) ? 1 : 0;
		}
	}
	return buffer[2];
}

ui64 tests[6] = {1, 13, 0, 998224353, 123456789, 1000000000 };

int main()
{
	V tmp = (a > zero) + (b > zero);
	pows[0] = tmp > zero;
	for (int i = 1; i < 60; ++i) pows[i] = pows[i - 1] + pows[i - 1];
	bpow[0] = b;
	for (int i = 1; i < 30; ++i) bpow[i] = bpow[i - 1] + bpow[i - 1];
	V ret = zero, added = zero;
	for (int i = 29; i >= 0; --i) {
		V flg = a > (added + pows[i]);
		ret = ret + cond(flg, bpow[i], i + 30);
		added = added + mulpow2(flg, i);
	}
	ret = ret + cond(a > zero, b, 30);
	Op.push_back('+');
	In1.push_back(zero.id_);
	In2.push_back(ret.id_);
	Out.push_back(2);

	printf("%d\n", Op.size());
	for (int i = 0; i < Op.size(); ++i) printf("%c %d %d %d\n", Op[i], In1[i], In2[i], Out[i]);

	for (int i = 0; i < 6; ++i) {
		for (int j = 0; j < 6; ++j) {
			ui64 expected = tests[i] * tests[j];
			ui64 ans = emulate(tests[i], tests[j]);
			if (expected != ans)
			printf("%llu %llu %llu %llu\n", tests[i], tests[j], emulate(tests[i], tests[j]), tests[i] * tests[j]);
		}
	}
	return 0;
}

