int a = 0, b = 1, nula = 1000, sol = 300, gate = 301;
int pot[LOG];
llint r[MAXN];

void cmp (int i, int j, int k) {
    cout << "< " << i << " " << j << " " << k << endl;
    r[k] = r[i] < r[j];
}

void add (int i, int j, int k) {
    cout << "+ " << i << " " << j << " " << k << endl;
    r[k] = r[i] + r[j];
}

void ispis (int lo, int hi) {
    for (int i = lo; i < hi; i++) cout << r[i] << " "; cout << endl;
}

void gen_pot () {
    add(0, 1, 2);
    add(2, 2, 2);
    cmp(0, 2, 2);
    pot[0] = 2;
    for (int i = 1; i < LOG; i++) {
        pot[i] = i + 2;
        add(pot[i - 1], pot[i - 1], pot[i]);
    }
}

void gen_bin (int pos, int val) {
    int curr = pos + 60, tmp = pos + 61;
    add(val, pot[0], val);

    for (int i = LOG - 1; i >= 0; i--) {
        add(curr, pot[i], tmp);
        cmp(tmp, val, pos + i);
        add(pos + i, nula, pos + i + 30);
        for (int j = 0; j < i; j++) {
            add(pos + i + 30, pos + i + 30, pos + i + 30);
        }
        add(curr, pos + i + 30, curr);
    }
}

void mult_bits (int pos_a, int pos_b, int i, int j) {
    add(pos_a + i, pos_b + j, gate);
    cmp(pot[0], gate, gate);
    for (int k = 0; k < i + j; k++) {
        add(gate, gate, gate);
    }
    add(sol, gate, sol);
}

void solve () {
    for (int i = 0; i < LOG; i++) {
        for (int j = 0; j < LOG; j++) {
            mult_bits(100, 200, i, j);
        }
    }
}

