        return {'+', r, z.r};
    }
    tuple<char, int, int> operator+(int z) {
        return {'+', r, z};
    }
    tuple<char, int, int> operator<(A z) {
        return {'<', r, z.r};
    }
    tuple<char, int, int> operator<(int z) {
        return {'<', r, z};
    }

    void operator=(int z) {ANS.emplace_back('+', z, 0, r);}
    void operator=(A z) {ANS.emplace_back('+', z.r, 0, r);}
    void operator+=(int z) {ANS.emplace_back('+', r, z, r);}
    void operator+=(A z) {ANS.emplace_back('+', r, z.r, r);}

    void operator=(tuple<char, int, int> t) {
        char c;
        int x, y;
        tie(c, x, y) = t;
        ANS.emplace_back(c, x, y, r);
    }
};
