vector<A> p(30);
A a, b, t, rv;
void select(A& x, A& b) {
    rv = 0;
    for(int i = 29; i >= 0; i--) {
        t = rv + p[i];
        t = t < x;
        t = t + b;
        t = 1 < t;
        rep(_, i) t += t;
        rv += t;
    }
    t = rv < x;
    t = t + b;
    t = 1 < t;
    rv += t;
}

