void from_binary(vector<Var> &vars, Var &target){
    target = target < target;
    for(int i = int(vars.size()) - 1;i >= 0;i--){        
        target = target + target;
        target = target + vars[i];
    }
}


Var zero;
Var one;

void into_binary(Var &source, vector<Var> &bin){
    int n = bin.size();
    Var source1;
    source1 = source + one;
    Var tmp;
    for(int i = n-1;i >= 0;i--){
        bin[i] = zero < one;
        from_binary(bin, tmp);
        bin[i] = tmp < source1;
    }
}

