struct Q {
    bool ty;
    int i, j, k;
};

const int N = 200000;
V<Q> solve(ull a, ull b) {
    V<Q> ques;
    V<ull> table(N);
    table[0] = a;
    table[1] = b;

    auto add = [&](int i, int j, int k) {
        ques.push_back({true, i, j, k});
        table[k] = table[i] + table[j];
    };

    auto cmp = [&](int i, int j, int k) {
        ques.push_back({false, i, j, k});
        table[k] = table[i] < table[j];
    };

    // table[i] <<= l
    auto mul2n = [&](int i, int l) {
        for (int ph = 0; ph < l; ph++) {
            add(i, i, i);
        }
    };

    int vc = 3;
    auto alc = [&]{ return vc++; };

    int A = 0, B = 1, Z = 2;
    int zero = alc();
    V<int> pw2(62, -1);
    {
        int buf0 = alc(), buf1 = alc(), buf2 = alc();
        cmp(A, B, buf0);
        cmp(B, A, buf1);
        add(buf0, buf1, buf2);
        mul2n(buf2, 40);

        cmp(A, buf2, buf0);
        cmp(buf2, A, buf1);
        add(buf0, buf1, buf2);

        assert(table[buf2] == 1);

        pw2[0] = buf2;
        for (int i = 1; i < 62; i++) {
            pw2[i] = alc();
            add(pw2[i - 1], pw2[i - 1], pw2[i]);
        }
        for (int i = 0; i < 62; i++) {
            assert(table[pw2[i]] == 1LL << i);
        }
    }
    int one = pw2[0];
    V<int> pw2n1(62, -1);
    {
        pw2n1[0] = zero;
        for (int i = 1; i < 62; i++) {
            pw2n1[i] = alc();
            add(pw2n1[i - 1], pw2[i - 1], pw2n1[i]);
        }
        for (int i = 0; i < 62; i++) {
            assert(table[pw2n1[i]] == (1LL << i) - 1);
        }
    }

    auto divide_bit = [&](int x) -> V<int> {
        V<int> v(31);
        int now = alc();
        for (int i = 30; i >= 0; i--) {
            v[i] = alc();
            int now2 = alc();
            add(now, pw2n1[i], now2);
            cmp(now2, x, v[i]);
            int now3 = alc();
            add(v[i], zero, now3);
            mul2n(now3, i);
            add(now, now3, now);
        }
        return v;
    };
    V<int> a_bit = divide_bit(A), b_bit = divide_bit(B);
    // dbg(a, b);
    // for (int i = 0; i < 31; i++) {
    //     dbg(table[a_bit[i]]);
    // }
    // for (int i = 0; i < 31; i++) {
    //     dbg(table[b_bit[i]]);
    // }
    {
        ll as = 0, bs = 0;
        for (int i = 0; i < 31; i++) {
            ll at = table[a_bit[i]];
            as += (at << i);
            if (at) {
                assert(a & (1 << i));
            }
            ll bt = table[b_bit[i]];
            bs += (bt << i);
            if (bt) {
                assert(b & (1 << i));
            }
        }
        assert((as == a) && (bs == b));
    }

    for (int i = 0; i < 31; i++) {
        for (int j = 0; j < 31; j++) {
            int buf = alc();
            add(a_bit[i], b_bit[j], buf);
            cmp(one, buf, buf);
            mul2n(buf, i + j);
            add(Z, buf, Z);
        }
    }

    assert(table[Z] == ll(a) * b);
                    ;
    return ques;
}


