  ops.push_back({LESS, ZERO, A, ONE});

  ops.push_back({PLUS, RES, ONE, RES});

  vector<int> pow2(30);
  pow2[0] = ONE;
  for (int i = 1; i < pow2.size(); ++i) {
    pow2[i] = regs++;
    ops.push_back({PLUS, pow2[i - 1], pow2[i - 1], pow2[i]});
  }

  int tmp1 = regs++;
  int tmp2 = regs++;
  int tmp3 = regs++;
  int tmp4 = regs++;
  auto split_to_bits = [&](int A) -> vector<int> {
    vector<int> bits(pow2.size());
    int made = regs++;
    for (int i = pow2.size() - 1; i >= 0; --i) {
      ops.push_back({PLUS, made, pow2[i], tmp1});
      ops.push_back({LESS, tmp1, A, tmp2});
      bits[i] = regs++;
      ops.push_back({PLUS, bits[i], tmp2, bits[i]});
      for (int j = 0; j < i; ++j) {
        ops.push_back({PLUS, tmp2, tmp2, tmp2});
      }
      ops.push_back({PLUS, made, tmp2, made});
    }
    ops.push_back({PLUS, RES, made, RES});
    return bits;
  };

  auto abits = split_to_bits(A);
  auto bbits = split_to_bits(B);

  for (int i = 0; i < (int)pow2.size(); ++i) {
    for (int j = 0; j < (int)pow2.size(); ++j) {
      ops.push_back({LESS, abits[i], ONE, tmp1});
      ops.push_back({LESS, bbits[j], ONE, tmp2});
      ops.push_back({PLUS, tmp1, tmp2, tmp3});
      ops.push_back({LESS, tmp3, ONE, tmp4});
      for (int k = 0; k < i + j; ++k) {
        ops.push_back({PLUS, tmp4, tmp4, tmp4});
      }
      ops.push_back({PLUS, RES, tmp4, RES});
    }
  }

  return ops;
}

