int main() {
    using op_type = std::tuple<char, ll, ll, ll>;
    vec<op_type> ov;

    // a = A, B, 0, 0, 1, 2, 4, ..., 2^32
    ll offset1 = 4;
    ll idx0 = 3, idx1 = 4;
    ov.emplace_back('+', 0, 1, 2);
    ov.emplace_back('<', 3, 2, offset1);
    for (ll i = 1; i <= 32; i++) {
        ov.emplace_back('+', i - 1 + offset1, i - 1 + offset1, i + offset1);
    }

    auto get_pow2 = [&](ll i) {
        return offset1 + i;
    };

    auto clear = [&](ll i) {
        ov.emplace_back('<', i, i, i);
    };

    clear(2);

    // if a[i], a[j+p] = 2^p, else a[j+p] = 0
    auto gen_pow2 = [&](ll i, ll j, ll p) {
        ov.emplace_back('<', idx0, i, j);
        for (ll d = 1; d <= p; d++) {
            ov.emplace_back('+', j + d - 1, j + d - 1, j + d);
        }
    };

    ll buf = 1000;
    ll buf2 = 1500;
    ll buf3 = 2000;

    // a[i:i+33] = rev of bits of a[idx] (e.g. if a[idx] == 3, a[i:i+33] = 110...0)
    auto gen_bits = [&](ll i, ll idx) {
        ll cur_sum = buf;
        clear(cur_sum);
        for (ll d = 32; 0 <= d; d--) {
            ov.emplace_back('+', cur_sum, get_pow2(d), cur_sum + 1);
            ov.emplace_back('<', cur_sum + 1, idx, buf2);
            gen_pow2(buf2, buf3, d);
            ov.emplace_back('<', idx0, buf3 + d, i + d);
            ov.emplace_back('+', cur_sum, buf3 + d, cur_sum);
        }
    };

    // a[k] = a[i] && a[j];
    auto get_and = [&](ll i, ll j, ll k, ll buf) {
        clear(k);
        ov.emplace_back('<', idx0, i, buf);
        ov.emplace_back('+', buf, k, k);
        ov.emplace_back('<', idx0, j, buf);
        ov.emplace_back('+', buf, k, k);
        ov.emplace_back('<', idx1, k, k);
    };

    ll offset2 = offset1 + 50;
    ll offset3 = offset2 + 50;

    ov.emplace_back('+', 0, idx1, 0);
    ov.emplace_back('+', 1, idx1, 1);

    gen_bits(offset2, 0);
    gen_bits(offset3, 1);

    for (ll i = 0; i <= 32; i++) for (ll j = 0; j <= 32; j++) {
        get_and(offset2 + i, offset3 + j, buf, buf + 1);
        gen_pow2(buf, buf + 1, i + j);
        ov.emplace_back('+', 2, buf + 1 + i + j, 2);
    }

    std::cout << ov.size() << "\n";
    for (auto [ a, b, c, d ] : ov) {
        std::cout << a << ' ' << b << ' ' << c << ' ' << d << "\n";
    }
    return 0;
}

