        i = i1;
        j = i2;
        k = i3;
    }

    char c;
    int i, j, k;

    void print() {
        cout << c << " " << i << " " << j << " " << k << endl;
    }
};

const int MX = 12;
vector<op> solve() {
    vector<op> res;

    int used = 3;

    const int ZERO = used++;

    const int CMP1 = used++;
    res.emplace_back(CMP, ZERO, 0, CMP1);

    const int CMP2 = used++;
    res.emplace_back(CMP, ZERO, 1, CMP2);

    const int SUM = used++;
    res.emplace_back(ADD, CMP1, CMP2, SUM);


    const int ONE = used++;
    res.emplace_back(CMP, ZERO, SUM, ONE);


    const int COUNTER_1 = used++;
    const int COUNTER_2 = used++;
    const int MAYBE_ONE = used++;
    const int MAYBE_ONE_2 = used++;
    const int MAYBE_A = used++;
    const int MAYBE_TWO = used++;
    const int REAL_ONE = used++;

    auto set_zero = [&](int id) {
        res.emplace_back(ADD, ZERO, ZERO, id);
    };

    set_zero(COUNTER_1);
    for (int i = 0; i < MX; i++) {
        res.emplace_back(CMP, COUNTER_1, 1, MAYBE_ONE);
        res.emplace_back(ADD, COUNTER_1, ONE, COUNTER_1);

        set_zero(COUNTER_2);
        set_zero(MAYBE_A);
        for (int j = 0; j < MX; j++) {
            res.emplace_back(CMP, COUNTER_2, 0, MAYBE_ONE_2);
            res.emplace_back(ADD, COUNTER_2, ONE, COUNTER_2);

            res.emplace_back(ADD, MAYBE_ONE, MAYBE_ONE_2, MAYBE_TWO);
            res.emplace_back(CMP, ONE, MAYBE_TWO, REAL_ONE);

            res.emplace_back(ADD, MAYBE_A, REAL_ONE, MAYBE_A);
        }
        res.emplace_back(ADD, 2, MAYBE_A, 2);
    }

    return res;
}

bool check(const vector<op> &res, int A, int B) {
    const int N = 2e5;
    vector<int> a(N);
    a[0] = A;
    a[1] = B;

    for (auto o : res) {
        if (o.c == ADD) {
            a[o.k] = a[o.i] + a[o.j];
        }
        if (o.c == CMP) {
            a[o.k] = a[o.i] < a[o.j];
        }
    }
    bool ok = (a[2] == 1LL * A * B);

    if (!ok) {
        db2(A, B);
        for (int i =0; i < 20; i++) cerr << a[i] << " ";
        cerr << endl;
    }
    return ok;
}

