struct Op {
  char c;
  vector<int> pos;
};

void solve(__attribute__((unused)) bool read) {
  const int C = 20;
  vector<Op> ops;
  int zero_pos = 2;
  ops.push_back({'+', {0, 1, C * C + 10}});
  ops.push_back({'<', {0, C * C + 10, C * C + 11}});
  ops.push_back({'<', {1, C * C + 10, C * C + 12}});
  ops.push_back({'+', {C * C + 11, C * C + 12, C * C + 13}});
  int one_pos = C * C + 14;
  ops.push_back({'<', {zero_pos, C * C + 13, one_pos}});
  for (int i = 0; i < C; ++i) {
    int pos = i * C + 3;
    ops.push_back({'+', {zero_pos, one_pos, pos}});
  }
  for (int i = 0; i < C; ++i) {
    int pos = i * C + 3;
    int prev = (i == 0 ? 2 : (pos - C));
    ops.push_back({'+', {prev, pos, pos}});
  }
  for (int i = C - 1; i >= 0; --i) {
    int pos = i * C + 3;
    int prev = (i == 0 ? 2 : (pos - C));
    ops.push_back({'<', {prev, 1, pos}});
  }
  int a = C * C + 20, b = C * C + 21, c = C * C + 22, d = C * C + 23;
  for (int i = 0; i < C; ++i) {
    int pos = i * C + 3;
    for (int j = 1; j < C; ++j) {
      ops.push_back({'+', {pos, pos + j - 1, pos + j}});
    }
    for (int j = 0; j < C; ++j) {
      ops.push_back({'<', {pos + j, 0, a}});
      ops.push_back({'<', {0, pos + j, b}});
      ops.push_back({'+', {a, b, c}});
      ops.push_back({'<', {c, one_pos, d}});
      ops.push_back({'<', {zero_pos, pos + j, pos + j}});
      ops.push_back({'+', {pos + j, d, d}});
      ops.push_back({'<', {one_pos, d, pos + j}});
    }
    for (int j = C - 2; j >= 0; --j) {
      ops.push_back({'+', {pos + j + 1, pos + j, pos + j}});
    }
  }
  for (int i = 0; i < C; ++i) {
    for (int j = 0; j < C; ++j) {
      ops.push_back({'+', {2, 3 + i * C + j, 2}});
    }
  }
  bool local = false;

  if (local) {
   for (int it = 0; it < 100; ++it) {
     vector<int> a(500, 0);
     a[0] = rand() % 11;
     a[1] = rand() % 11;
     int need = a[0] * a[1];
     for (auto& op : ops) {
       if (op.c == '+') {
         a[op.pos[2]] = a[op.pos[0]] + a[op.pos[1]];
       } else {
         a[op.pos[2]] = (a[op.pos[0]] < a[op.pos[1]]);
       }
       /*for (int x : a) {
         cout << x << " ";
       }
       cout << endl;*/
     }
     if (a[2] != need) {
       cerr << "FOUND A: " << a[0] << " B: " << a[1] << " need: " << need << " res: " << a[2] << endl;
       return;
     }
   }
  } else {
    cout << ops.size() << "\n";
    for (auto &op : ops) {
      cout << op.c;
      for (int x : op.pos) {
        cout << " " << x;
      }
      cout << "\n";
    }
  }

}

