const int ITER = 15;
void solve() {
	const int COUNTER = 9;
	const int ZERO = 10;
	const int ONE = 11;

	const int ADDER = 4;
	const int SUM = 5;
	const int IND = 6;
	const int IND2 = 7;
	const int IND3 = 8;

	les(ONE, 0, ONE);
	for (int i = 1; i <= ITER; i++) {
		les(COUNTER, 0, IND);
		les(IND, ONE, IND);
		add(ZERO, ZERO, SUM);
		add(ZERO, ZERO, ADDER);

		for (int j = 1; j <= ITER; j++) {
			les(SUM, 1, IND2);
			les(IND2, ONE, IND2);

			add(IND, IND2, IND3);
			les(IND3, ONE, IND3);

			add(ZERO, ZERO, ADDER);
			add(ZERO, IND3, ADDER);

			add(SUM, ADDER, SUM);
		}

		add(2, SUM, 2);
		add(COUNTER, ONE, COUNTER);
	}
}

