  };
  auto compare = [&](int i, int j, int k) {
    res.push_back("< " + to_string(i) + " " + to_string(j) + " " + to_string(k));
  };
  vector<int> num(bit);
  vector<int> power(bit);
  for(int i = bit - 1; i >= 0; i--) {
    num[i] = n - 1 - i;
    power[i] = num[i] - bit;
  }
  compare(2, 0, num[1]);
  compare(2, 1, num[2]);
  add(num[1], num[2], num[1]);
  compare(num[0], num[1], num[1]);
  for(int i = 2; i < bit; i++) {
    add(num[i - 1], num[1], num[i]);
  }
  for(int i = 1; i < bit; i++) {
    add(power[i - 1], power[i - 1], power[i]);
    add(power[i], num[1], power[i]);
  }
  vector<int> go(2);
  for(int pos = 0; pos <= 1; pos++) {
    for(int i = 2; i < b + 2; i++) {
      add(power[i - 2], num[0], i);
    }
    for(int st = b + 2 + pos * b; st < 2 * b + 2 + pos * b; st++) {
      for(int j = st; j < st + b; j++) {
        compare(j - st + 2, pos, j);
        if(j > st + 1) {
          int v = j - st - 1;
          while(v--) {
            add(j, j, j);
          }
        }
      }
      for(int j = st + 1; j < st + b; j++) add(st, j, st);
      for(int i = 2; i < b + 2; i++) add(i, st, i);
    }
    go[pos] = b + 2 + pos * b;
  }
  vector<int> go_log(2);
  go_log[0] = go[0] + 2 * b;
  go_log[1] = go[1] + 2 * b;
  for(int pos = 0; pos <= 1; pos++) {
    for(int i = go[pos]; i < go[pos] + b; i++) {
      for(int j = i + 2 * b; j < i + 3 * b - 1; j++) {
        compare(power[j - i - 2 * b + 1], i, j);
      }
      for(int j = i + 1 + 2 * b; j < i + 3 * b - 1; j++) {
        add(i + 2 * b, j, i + 2 * b);
      }
    }
  }
  int sum = n >> 1;
  int cnt = sum >> 1;
  add(num[0], num[0], 2);
  for(int i = 0; i < b; i++) {
    for(int j = 0; j < b; j++) {
      compare(num[0], go[0] + i, cnt);
      compare(num[0], go[1] + j, cnt + 1);
      add(cnt, cnt + 1, cnt);
      compare(num[1], cnt, cnt);
      add(2, cnt, 2);
      add(go_log[0] + i, go_log[1] + j, cnt + 1);
      int bound = b - 1 - i + (b - 1 - j);
      for(int p = cnt + 2; p < cnt + 2 + bound; p++) {
        compare(num[p - cnt - 2], cnt + 1, p);
        add(p, cnt, p);
        compare(num[1], p, p);
        add(p, sum + p - cnt - 2, sum + p - cnt - 2);
      }
    }
  }
  for(int i = sum; i < sum + bit; i++) {
    int v = i - sum;
    while(v--) {
      add(i, i, i);
    }
    add(2, i, 2);
  }
  cout << res.size() << "\n";
  for(auto i : res) cout << i << "\n";
  return 0;
}

