void pl(int i, int j, int k){
    cout << "+ " << i << " " << j << " " << k << endl;
}

void cmp(int i, int j, int k){
    cout << "< " << i << " " << j << " " << k << endl;
}

void Main(){
    // a[3] = 0, a[4] = 1, a[5] = 2, a[6] = 3, ..., a[12] = 9
    cmp(3, 0, 4);
    rep3(i, 4, 11) pl(4, i, i+1);

    // a[20] = a[3] < A, a[29] = a[12] < A
    rep(i, 10) cmp(i+3, 0, i+20);
    // a[30] = B < a[3], a[29] = B < a[12]
    rep(i, 10) cmp(1, i+3, i+30);

    // a[100] - a[199]
    rep(i, 10){
        rep(j, 10){
            cmp(j+30, i+20, 100 + j + 10*i); 
        }
    }

    // a[200] - a[299]
    pl(99, 100, 200);
    rep(i, 100){
        pl(100+i, 200+i, 200+i+1);
    }    
    pl(300, 3, 2);
    return;
}

