mt19937 mt(736);

const int n = (int) 2e5;


ull simulate(const vector<tuple<char, int, int, int>> &arr, int a, int b)
{
	array<ull, n> mem{0};

	mem[0] = a;
	mem[1] = b;

	for (auto it : arr)
		if (get<0>(it) == '+')
			mem[get<3>(it)] = mem[get<1>(it)] + mem[get<2>(it)];
		else
			mem[get<3>(it)] = mem[get<1>(it)] < mem[get<2>(it)] ? 1 : 0;

	return mem[2];
}


void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
	vector<tuple<char, int, int, int>> arr;

	const auto zero = n - 1;
	const auto one = zero - 1;

	arr.emplace_back('+', 0, 1, one);
	arr.emplace_back('<', zero, one, one);

	for (int i = 2; i <= 10; i++)
		arr.emplace_back('+', zero - (i - 1), one, zero - i);

	auto tmp = zero - 736;

	for (int a = 0; a <= 10; a++)
		for (int b = 0; b <= 10; b++)
		{
			arr.emplace_back('<', zero - a, 0, tmp);
			arr.emplace_back('<', zero - b, 1, tmp + 1);
			arr.emplace_back('+', tmp, tmp + 1, tmp + 2);
			arr.emplace_back('<', one, tmp + 2, tmp + 3);
			arr.emplace_back('+', 2, tmp + 3, 2);
		}

	cout << arr.size() << endl;

	for (const auto &it : arr)
	{
		char op;
		int a, b, c;

		tie(op, a, b, c) = it;

		cout << op << ' ' << a << ' ' << b << ' ' << c << endl;
	}

	for (int a = 0; a <= 10; a++)
		for (int b = 0; b <= 10; b++)
			assert(simulate(arr, a, b) == a * b);
}


