/*
v[j] is guaranteed to be 0 or 1
*/

int ptr = 3;
int const lgmax = 30;

void quick_raise(int x, int p){
  for(int h = 1; h <= p; h++)
    add(x, x, x);
}

int const sure_zero = 200000 - 1;
int const sure_one =  200000 - 2;
int const sure_use =  200000 - 3;

void compare_equal(int x, int y, int k) {
  add(y, sure_one, sure_use);
  compare(x, sure_use, k);
}

void multiply_simple(int i, int j, int k) {
  add(j, sure_zero, ptr);
  for(int h = 1; h < lgmax; h++) 
    add(ptr + h - 1, ptr + h - 1, ptr + h);

  int aux = ptr + lgmax;
  int total = ptr + lgmax + 1;
  for(int h = lgmax - 1; 0 <= h; h--) {
    add(total, ptr + h, aux);
    compare_equal(aux, i, aux);

    quick_raise(aux, h);
    add(total, aux, total);
  }
  ptr += lgmax + 2;
  add(total, sure_zero, k);
}

void multiply_hard(int i, int j, int k) {
  int start_ptr = ptr;
  add(sure_one, sure_zero, start_ptr);

  for(int h = 1; h < lgmax; h++)
    add(start_ptr + h - 1, start_ptr + h - 1, start_ptr + h);

  int aux = ptr + lgmax, aux2 = ptr + lgmax + 3;
  int total = ptr + lgmax + 2, coef = ptr + lgmax + 1;
  ptr += lgmax + 4;

  for(int h = lgmax - 1; 0 <= h; h--) {
    add(coef, start_ptr + h, aux);
    compare_equal(aux, j, aux);

    add(aux, sure_zero, aux2);
    quick_raise(aux, h);
    multiply_simple(i, aux2, aux2);
    quick_raise(aux2, h);
    add(aux, coef, coef);
    add(aux2, total, total);
  }
  add(total, sure_zero, k);
}

int main() {
  compare(2, 0, sure_one);
  ptr = 3; 
  multiply_hard(0, 1, 2);
  std::cout << sol.size() << '\n';
  for(int i = 0; i < sol.size(); i++)
    std::cout << sol[i].ch << " " << sol[i].i << " " << sol[i].j << " " << sol[i].k << '\n';
  return 0;
}

