using namespace std;
const int MAXN = 3e5 + 5;
const int n = 31;
typedef long long ll;
template <typename T> void chkmax(T &x, T y) {x = max(x, y); }
template <typename T> void chkmin(T &x, T y) {x = min(x, y); } 
template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
struct info {
	char opt;
	int i, j, k;
};
vector <info> ans; int v[MAXN];
int a, b, res, p, q, two[MAXN], zero, cnt;
void check() {
	read(v[0]), read(v[1]);
	for (auto x : ans) {
		if (x.opt == '<') v[x.i] = v[x.j] < v[x.k];
		else v[x.i] = v[x.j] + v[x.k];
	}
	cerr << v[2] << endl;
}
int cmp(int x, int y) {
	ans.push_back((info) {'<', ++cnt, x, y});
	return cnt;
}
int add(int x, int y) {
	ans.push_back((info) {'+', ++cnt, x, y});
	return cnt;
}
int power(int x, int y) {
	if (y == 0) return x;
	else {
		int res = power(x, y - 1);
		return add(res, res);
	}
}
void update(int x, int y, int z) {
	int cur = cmp(two[0], add(x, y));
	cur = power(cur, z);
	ans.push_back((info) {'+', res, res, cur});
}
int getone() {
	int x = cnt + 1;
	ans.push_back((info) {'+', ++cnt, a, b});
	ans.push_back((info) {'<', ++cnt, zero, x});
	return cnt;
}
void work(int flg, int x, int b) {
	int q = ++cnt;
	for (int i = n; i >= 0; i--) {
		int glg = cmp(add(q, two[i]), b);
		update(flg, glg, x + i), q = add(q, power(glg, i));
	}
	int glg = cmp(q, b);
	update(flg, glg, x);
}
int main() {
	a = 0, b = 1, res = 2, zero = cnt = 3;
	two[0] = getone();
	for (int i = 1; i <= n * 2; i++)
		two[i] = add(two[i - 1], two[i - 1]);
	int p = ++cnt;
	for (int i = n; i >= 0; i--) {
		int flg = cmp(add(p, two[i]), a);
		work(flg, i, b), p = add(p, power(flg, i));
	}
	int flg = cmp(p, a);
	work(flg, 0, b);
	cout << ans.size() << endl;
	for (auto x : ans) printf("%c %d %d %d\n", x.opt, x.j, x.k, x.i);
	//check();
	return 0;
}

