  cin.tie(0);
  int a = 0, b = 1;
  int ans = 2;
  int zero = 3;
  int sz = 4;
  vector <op> e;
  auto sum_query = [&] (int i, int j, int k) {
    reg[k] = reg[i] + reg[j];
    e.push_back({'+', i, j, k});
  };
  auto sum = [&] (int i, int j) {
    int k = sz++;
    sum_query(i, j, k);
    return k;
  };
  auto less = [&] (int i, int j) {
    int k = sz++;
    reg[k] = (reg[i] < reg[j]);
    e.push_back({'<', i, j, k});
    return k;
  };
  int tot = sum(a, b);
  int one = less(zero, tot);
  auto AND = [&] (int i, int j) {
    int x = sum(i, j);
    return less(one, x);
  };
  vector <int> pw(64);
  pw[0] = one;
  for (int i = 1; i < 64; i++) {
    pw[i] = sum(pw[i - 1], pw[i - 1]);
  }
  int a_plus_1 = sum(a, one);
  int b_plus_1 = sum(b, one);
  auto shift = [&] (int s, int j) {
    for (int i = 1; i <= j; i++) {
      s = sum(s, s);
    }
    return s;
  };
  auto binary = [&] (int p) {
    int cur = zero;
    vector <int> ord(32);
    for (int i = 31; i >= 0; i--) {
      int x = sum(cur, pw[i]);
      int check = less(x, p);
      int here = shift(check, i);
      cur = sum(cur, here);
      ord[i] = check;
    }
    return ord;
  };
  auto x = binary(a_plus_1), y = binary(b_plus_1);
  vector <int> s(64);
