    s[i] = zero;
  }
  for (int i = 0; i < 32; i++) {
    for (int j = 0; j < 32; j++) {
      int cur = AND(x[i], y[j]);
      s[i + j] = sum(s[i + j], cur);
    }
  }
  ans = zero;
  for (int i = 0; i < 64; i++) {
    ans = sum(ans, shift(s[i], i));
  }
  sum_query(ans, zero, 2);
  cout << e.size() << '\n';
  for (auto c : e) {
    cout << c.x << ' ' << c.a << ' ' << c.b << ' ' << c.c << '\n';
  }
}

