const int MAX_LG = 60;
const int TPOWS = 100;
void init_tpow () {
  add(TPOWS, ONE, TPOWS);
  for (int i = 1; i < MAX_LG; i++) {
    add(TPOWS + i - 1, TPOWS + i - 1, TPOWS + i);
  }
}

const int ABIN = 200;
const int BBIN = 300;
void to_bin (int orig, int sta) {
  int HOLD = 10;
  int AUX = 11;
  add(ZRO, ZRO, HOLD);
  for (int i = MAX_LG - 1; i >= 0; i--) {
    add(HOLD, TPOWS + i, AUX);
    lt(orig, AUX, AUX);
    not_(AUX, AUX);
    // if we ought to add it to HOLD it is 1 now

    add(ZRO, AUX, sta + i);
    for (int j = 0; j < i; j++) {
      add(AUX, AUX, AUX);
    }
    add(AUX, HOLD, HOLD);
  }
}

const int CBIN = 400;
void add_bin (int asta, int bsta, int cond) { // if cond bsta += asta
  int AUX = 12, BUX = 13;
  for (int i = 0; i < MAX_LG; i++) {
    and_(cond, asta + i, AUX);
    add(AUX, bsta + i, bsta + i);
  }

  for (int i = 0; i < MAX_LG; i++) {
    lt(ONE, bsta + i, AUX);
    add(AUX, bsta + i + 1, bsta + i + 1);
    lt(bsta + i, TPOWS + 1, AUX);
    lt(TPOWS + 1, bsta + i, BUX);
    or_(AUX, BUX, BUX);
    lt(ZRO, bsta + i, AUX);
    and_(AUX, BUX, bsta + i);
  }
}

void dbl_bin (int sta) {
  for (int i = MAX_LG - 1; i > 0; i--) {
    add(sta + i - 1, ZRO, sta + i);
  }
  add(ZRO, ZRO, sta);
}


int main () {
  init_one();
  init_tpow();

  to_bin(A, ABIN);
  to_bin(B, BBIN);

  for (int i = 0; i < MAX_LG; i++) {
    add_bin(ABIN, CBIN, BBIN + i);    
    dbl_bin(ABIN);
  }

  for (int i = 0; i < MAX_LG; i++) {
    for (int j = 0; j < i; j++) {
      add(CBIN + i, CBIN + i, CBIN + i);
    }
    add(CBIN + i, TAR, TAR);
  }

  cout << (int) ans.size() << endl;
  for (Op o : ans) {
    cout << o << '\n';
  }
}

