  rep(i, 0, 64) P2[i] = alloc();

  // generate constants
  {
    // Generate C[1]
    int t = alloc();
    add(t, A, B);
    cmp(C[1], C[0], t);
    bassert(mem[C[1]], int(0 < (mem[A] + mem[B])));
  }
  rep(i, 2, 11) {
    add(C[i], C[i - 1], C[1]);
    bassert(mem[C[i]], i);
  }

  add(P2[0], P2[0], C[1]);
  rep(i, 1, 64) {
    add(P2[i], P2[i - 1], P2[i - 1]);
    bassert(mem[P2[i]], 1ull << i);
  }

  // calculation
  {
    int acc = alloc(), t1 = alloc(), t2 = alloc(), t3 = alloc();
    rep(i, 1, 11) rep(j, 1, 11) {
      cmp(t1, C[i - 1], A);
      cmp(t2, C[j - 1], B);
      band(t3, t1, t2);
      add(acc, acc, t3);
      bassert(t3, int(mem[A] >= i && mem[B] >= j));
    }

    bassert(mem[acc], mem[A] * mem[B]);

    add(2, 2, acc);
  }

  write(ops.size());
