void bor(int k, int i, int j) {
  add(k, i, j);
  cmp(k, C[0], k);
}
void band(int k, int i, int j) {
  add(k, i, j);
  cmp(k, C[1], k);
}
void bnot(int k, int i) {
  cmp(k, i, C[1]);
}
void sub(int k, int i, int j) {
  int acc = alloc();
  mov(acc, C[0]);

  int ip1 = alloc();
  add(ip1, i, C[1]);

  int t1 = alloc(), t2 = alloc();
  repd(d, 29, 0) {
    // k = i - j -> k + j = =i
    add(t1, acc, j);
    add(t1, t1, P2[d]);
    cmp(t2, t1, ip1);

    debug("t1 = acc [%llu] + 2^%d [%llu] = %llu\n", mem[acc], d, mem[P2[d]], mem[t1]);

    rep(e, 0, d) add(t2, t2, t2); /// t2 <<= d
    add(acc, acc, t2);
  }

  debug("%llu = %llu - %llu\n", mem[acc], mem[i], mem[j]);
  bassert(mem[acc], mem[i] >= mem[j] ? mem[i] - mem[j] : 0ull);
  mov(k, acc);
}
void if0(int k, int cond, int val) {
  ull o_cond = mem[cond], o_val = mem[val];  

  int ncond = alloc();
  bnot(ncond, cond);
  rep(i, 0, 30) add(ncond, ncond, ncond); // cond <<= 30
  mov(k, val);

  debug("k = k [%llu] - ncond [%llu]\n", mem[k], mem[ncond]);
  sub(k, k, ncond);

  debug("cond: %llu, ncond: %llu\n", mem[cond], mem[ncond]);
  debug("original condition: %llu, value: %llu\n", o_cond, o_val);
  debug("retval: %llu\n", mem[k]);
  bassert(mem[k], o_cond ? o_val : 0);
}

