int idx, one, zero, a[30], b[30], c[60], q[30];

inline void plus(int src1, int src2, int dst) {
	printf("+ %d %d %d\n", src1, src2, dst);
}
inline void less(int src1, int src2, int dst) {
	printf("< %d %d %d\n", src1, src2, dst);
}
void prepare() {
	idx = 2;
	for (int i = 0; i < 30; i++) {
		a[i] = ++idx;
	}
	for (int i = 0; i < 30; i++) {
		b[i] = ++idx;
	}
	for (int i = 0; i < 59; i++) {
		c[i] = ++idx;
	}
	for (int i = 0; i < 30; i++) {
		q[i] = ++idx;
	}
	zero = q[0];
	one = q[1];
	plus(0, 1, 2);
	less(0, 2, 3);
	less(1, 2, one);
	plus(3, one, one);
	less(zero, one, one);
	for (int i = 2; i < 30; i++) {
		plus(q[i - 1], q[i - 1], q[i]);
		plus(q[i], one, q[i]);
	}
}
inline void getBit(int *bit, int src) {
	int num = ++idx, pow = ++idx;
	for (int i = 29; i >= 0; i--) {
		plus(num, q[i], bit[i]);
		less(bit[i], src, bit[i]);
		plus(bit[i], zero, pow);
		for (int j = 0; j < i; j++) {
			plus(pow, pow, pow);
		}
		plus(num, pow, num);
	}
}
inline void calc() {
	int num = ++idx;
	for (int i = 0; i < 30; i++) {
		for (int j = 0; j < 30; j++) {
			plus(a[i], b[j], num);
			less(one, num, num);
			plus(num, c[i + j], c[i + j]);
		}
	}
	for (int i = 0; i < 59; i++) {
		for (int j = 0; j < i; j++) {
			plus(c[i], c[i], c[i]);
		}
	}
}
