        jog(ZERO, ZERO, TOBINARY+MAXLOG);
        for (int j = 0; j < MAXLOG; j++) {
            for (int k = 0; k < j; k++) {
                jog(TOBINARY+j, TOBINARY+j, TOBINARY+j);
