struct Op {
  char op;
  int i, j, k;

  Op (char _op = '.', int _i = 0, int _j = 0, int _k = 0) :
    op(_op), i(_i), j(_j), k(_k) {}
};

ostream &operator<< (ostream &out, Op o) {
  out << o.op << " " << o.i << " " << o.j << " " << o.k;
  return out;
}

vector<Op> ans;

int simul (int a, int b) {
  vector<int> arr (30, 0);
  arr[0] = a;
  arr[1] = b;
  for (Op op : ans) {
    if (op.op == '<') {
      arr[op.k] = arr[op.i] < arr[op.j];
    } else {
      arr[op.k] = arr[op.i] + arr[op.j];
    }
  }
  return arr[2];
}

void add (int i, int j, int k) {
  ans.push_back(Op('+', i, j, k));
}

void lt (int i, int j, int k) {
  ans.push_back(Op('<', i, j, k));
}

const int A = 0;
