const int ZRO = 6;
void init_one () {
  add(A, B, ONE);
  lt(ZRO, ONE, ONE);
}

void and_ (int i, int j, int k) {
  add(i, j, k);
  lt(ONE, k, k);
}

void or_ (int i, int j, int k) {
  add(i, j, k);
  lt(ZRO, k, k);
}

void not_ (int i, int k) {
  lt(i, ONE, k); // if i = 0 k = 1 otherwise k = 0
}

const int MAX_LG = 60;
const int TPOWS = 100;
void init_tpow () {
  add(TPOWS, ONE, TPOWS);
  for (int i = 1; i < MAX_LG; i++) {
    add(TPOWS + i - 1, TPOWS + i - 1, TPOWS + i);
  }
}

const int ABIN = 200;
const int BBIN = 300;
void to_bin (int orig, int sta) {
  int HOLD = 10;
  int AUX = 11;
  add(ZRO, ZRO, HOLD);
  for (int i = MAX_LG - 1; i >= 0; i--) {
    add(HOLD, TPOWS + i, AUX);
    lt(orig, AUX, AUX);
    not_(AUX, AUX);
    // if we ought to add it to HOLD it is 1 now

    add(ZRO, AUX, sta + i);
    for (int j = 0; j < i; j++) {
      add(AUX, AUX, AUX);
    }
    add(AUX, HOLD, HOLD);
  }
}

const int CBIN = 400;
void add_bin (int asta, int bsta, int cond) { // if cond bsta += asta
  int AUX = 12, BUX = 13;
  for (int i = 0; i < MAX_LG; i++) {
    and_(cond, asta + i, AUX);
    add(AUX, bsta + i, bsta + i);
  }

  for (int i = 0; i < MAX_LG; i++) {
    lt(ONE, bsta + i, AUX);
    add(AUX, bsta + i + 1, bsta + i + 1);
    lt(bsta + i, TPOWS + 1, AUX);
    lt(TPOWS + 1, bsta + i, BUX);
    or_(AUX, BUX, bsta + i);
