int tot = 2; int nd() { return ++ tot; }

int Z, O;

int cnt;
stringstream ss;

void qadd(int i, int j, int k) { ++ cnt; ss << "+ " << i << " " << j << " " << k << endl; }
void qless(int i, int j, int k) { ++ cnt; ss << "< " << i << " " << j << " " << k << endl; }
void qgreater(int i, int j, int k) { qless(j, i, k); }
void qnot(int k) { qless(k, O, k); }
void qleq(int i, int j, int k) { qless(j, i, k); qnot(k); }
void qgeq(int i, int j, int k) { qgreater(j, i, k); qnot(k); }

int mul_1bit(int i, int j) {
	int k = nd();
	qadd(i, j, k);
	qgreater(k, O, k);
	return k;
}

void init() {
	Z = nd();
	O = nd(); qless(Z, 0, O);
}

int get_2k(int x, int k) {
	int y = nd();
	qadd(x, y, y);
	rep(i, k) qadd(y, y, y);
	return y;
}

vector <int> get_bin(int x) {
	vector <int> v;
	int s = nd();
	for (int i = 30 - 1; ~i; -- i) {
		int ns = nd();
		qadd(get_2k(O, i), s, ns);
		int k = nd();
		qleq(ns, x, k);
		qadd(get_2k(k, i), s, s);
		v.pb(k);
	}
	reverse(v.begin(), v.end());
	return v;
}

