int main(){
    using namespace std;

    constexpr unsigned long N{200000}, register_length{100}, reg{N - register_length + 1}, one_reg{reg - 1};

    unsigned long cnt{0};
    vector<unsigned long> sim(N), cntr(N);
    vector<tuple<bool, unsigned long, unsigned long, unsigned long>> qs;
    const auto& cmp = [&cnt, &sim, &qs, &cntr](unsigned long i, unsigned long j, unsigned long k) -> void {
        //cout << "< " << i << " " << j << " " << k << endl;
        qs.emplace_back(false, i, j, k);
        ++cntr[i];
        ++cntr[j];
        ++cntr[k];
        ++cnt;
        sim[k] = static_cast<unsigned long>(sim[i] < sim[j]);
    };
    const auto& add = [&cnt, &sim, &qs, &cntr](unsigned long i, unsigned long j, unsigned long k) -> void {
        //cout << "+ " << i << " " << j << " " << k << endl;
        qs.emplace_back(true, i, j, k);
        ++cntr[i];
        ++cntr[j];
        ++cntr[k];
        ++cnt;
        sim[k] = sim[i] + sim[j];
    };
    const auto& set_one = [&cmp, &add]() -> void {
        add(0, 1, one_reg);
        cmp(2, one_reg, one_reg);
    };
    const auto& bit_and_add = [&cmp, &add](unsigned long i, unsigned long j, unsigned long k) -> void {
        add(i, j, reg);
        cmp(one_reg, reg, reg + 1);
        add(k, reg + 1, k);
    };
    const auto& binary_mul = [&add, &bit_and_add](unsigned long i, unsigned long i_len, unsigned long j, unsigned long j_len, unsigned long k) -> void {
        for(unsigned long itr{0}; itr < i_len + j_len - 1; ++itr){
            if(itr)add(k, k, k);
            for(unsigned long jtr{0}; jtr <= itr; ++jtr)if(jtr < j_len && jtr + i_len > itr)bit_and_add(i + itr - jtr, j + jtr, k);
        }
    };
    const auto& int_to_bin = [&sim, &cmp, &add](unsigned long idx, unsigned long i, unsigned long len, unsigned long j) -> void {
        for(unsigned long itr{0}; itr < len; ++itr){
            if(itr)add(j + itr - 1, j + itr - 1, j + itr);
            add(j + itr, one_reg, j + itr);
            for(unsigned long jtr{itr}; jtr + 1 < len; ++jtr)add(j + jtr, j + jtr, j + jtr + 1);
            cmp(j + len - 1, idx, i + itr);
            add(j + itr - 1, j + itr - 1, j + itr);
            add(j + itr, i + itr, j + itr);
        }
    };

    cout << 3930 << endl;
    sim[0] = 100;
    sim[1] = 1987;
    set_one();
    add(0, one_reg, 3);
    add(1, one_reg, 4);
    int_to_bin(3, 100, 30, 130);
    int_to_bin(4, 130, 30, 230);
    binary_mul(100, 30, 130, 30, 2);
    vector<unsigned long> inv(N);
    iota(begin(inv), end(inv), 0UL);
    sort(begin(inv) + 3, end(inv), [&cntr](auto i, auto j){return cntr[i] > cntr[j];});
    vector<unsigned long> idx(N);
    for(unsigned long i{0}; i < N; ++i)idx[inv[i]] = i;
    for(const auto& [f, i, j, k] : qs)cout << (f ? "+ " : "< ") << idx[i] << " " << idx[j] << " " << idx[k] << endl;
    cerr << sim[2] << " : " << cnt << endl;
    return 0;
}

