            gum(i, j, 5000);
            pq(n - 1, 5000, 5000);
            gum(5000, i + j + 964, i + j + 964);
        }
    }
    for (int i = 2057; i >= 2000; i--)
    {
        gum(i, i + 1, i);
        gum(i, i + 1, i);
    }
    pq(n - 1, n, 3);
    gum(3, 2000, 3);
    return 0;
}

