struct Query {
    char opt;
    int i, j, k;

    Query() {}

    Query(char opt, int i, int j, int k): opt(opt), i(i), j(j), k(k) {}
};


int64_t a[N];
vector<Query> res;


void askSum(int i, int j, int k) {
    res.push_back(Query('+', i, j, k));
    a[k] = a[i] + a[j];
}


void askCompare(int i, int j, int k) {
    res.push_back(Query('<', i, j, k));
    a[k] = (a[i] < a[j]);
}


void buildPow2(int pos, int deg) {
    askSum(N - 2, N - 3, pos);

    for (int i = 0; i < deg; ++i) {
        askSum(pos, pos, pos);
    }
}


void zeroReset(int pos) {
    askSum(N - 3, N - 4, pos);
}


void buildOne(int pos) {
    askCompare(pos, 0, pos);    
}


void binaryMul(int i, int j, int pos) {
    askCompare(N - 3, i, N - 6);
    askCompare(N - 3, j, N - 7);

    askSum(N - 6, N - 7, pos);
    askCompare(N - 2, pos, pos);

    zeroReset(N - 6);
    zeroReset(N - 7);
}


void trace() {
    for (int i = 1; i <= N; ++i) {
        if (a[i]) {
            cerr << i << ": " << a[i] << '\n';
