constexpr int nbit = 32;

enum cells_layout {
    a = 0,
    b,
    final_result, 
    sum,
    zero,
    one,
    temp1,
    temp2,
    temp3,
    bin_a_reg,
    bin_b_reg = bin_a_reg + nbit,
    temp_reg = bin_b_reg + nbit
};

struct op {
    char type;
    int res, x, y;
    op() {}
    op(char t, int r, int u, int v): type(t), res(r), x(u), y(v) {}
};

ostream& operator<<(ostream& out, const op& u) {
    return out << u.type << ' ' << u.x << ' ' << u.y << ' ' << u.res;
}

vector<op> ops;

void add(int result, int x, int y) {
    ops.emplace_back('+', result, x, y);
}

void cmp_less(int result, int x, int y) {
    ops.emplace_back('<', result, x, y);
}


void cmp_greater(int result, int x, int y) {
    cmp_less(result, y, x);
}

void bin_not(int cell) {
    cmp_less(cell, cell, one);
}

void bin_and(int result, int x, int y) {
    add(result, x, y);
    cmp_less(result, zero, result);
}

template<bool keep = true>
void bin_or(int result, int x, int y) {
    bin_not(x);
    bin_not(y);
    bin_and(result, x, y);
    bin_not(result);
    if (!keep) return ;
    bin_not(x);
    bin_not(y);
}

void cmp_eq(int result, int x, int y, int temp = temp1) {
    cmp_less(temp, x, y);
    cmp_less(result, y, x);
    bin_not(temp);
    bin_not(result);
    bin_and(result, result, temp);
}

void bin_xor(int result, int x, int y, int temp = temp1) {
    cmp_eq(result, x, y, temp);
    bin_not(result);
}

void cmp_less_eq(int result, int a, int b) {
    cmp_greater(result, a, b);
    bin_not(result);
}

void cmp_greater_eq(int result, int a, int b) {
    cmp_less(result, a, b);
    bin_not(result);
}

void set_one(int cell) {
    cmp_less(cell, a, sum);
}

void set_zero(int cell) {
    cmp_less(cell, sum, a);
}

void shl(int cell, int cnt = 1) {
    while (cnt--) add(cell, cell, cell);
}

void to_bin(int num, int res, int temp_region) {
    set_zero(temp2);

    for (int i = nbit; i--; ) {
        set_one(temp1);
        rep(f, nbit) {
            add(temp3, temp1, temp2);
            cmp_greater_eq(temp_region + f, num, temp3);
            shl(temp1);
        }

        set_zero(temp2);
        rep(f, nbit) {
            int nxt = f == (nbit - 1) ? zero : temp_region + f + 1;
            cmp_less(temp_region + f, nxt, temp_region + f);
            bin_or(res + f, res + f, temp_region + f);
            add(temp1, zero, res + f);
            shl(temp1, f);
            add(temp2, temp2, temp1);
        }
    }
}

void mul(int result, int reg1, int reg2) {
    set_zero(result);
    rep(i, nbit) rep(f, nbit) {
        bin_and(temp1, reg1 + i, reg2 + f);
        shl(temp1, i + f);
        add(result, result, temp1);
    }
}

int main(void) {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    add(sum, a, b);
    set_one(one);
    set_zero(zero);

