const bool CMP  = false;
const bool PLUS = true;

struct ex {
	bool op; // 0:<,   1:+
	int a, b;
	int z;
	ex(bool op, int a, int b, int z) : op(op), a(a), b(b), z(z) {};
};


pair<bool, ll> test(const vector<ex> e, const int a, const int b, const bool debug = false) {
	vector<ll> v(200000);
	v[0] = a;
	v[1] = b;
	for (const auto z : e) {
		if (z.op == CMP) { // <
			if (debug) printe("v[%3d] = (v[%3d] < v[%3d]) = (%2lld < %2lld) = %2d\n", z.z, z.a, z.b, v[z.a], v[z.b], int(v[z.a] < v[z.b]));

			v[z.z] = (v[z.a] < v[z.b]);
		} else { // +
			if (debug) printe("v[%3d] = (v[%3d] + v[%3d]) = (%2lld + %2lld) = %2lld\n", z.z, z.a, z.b, v[z.a], v[z.b], (v[z.a] + v[z.b]));

			v[z.z] = (v[z.a] + v[z.b]);
		}
	}
	return { v[2] == a * b, v[2] };
}


vector<ex> build() {
	vector<ex> ret;

	ret.emplace_back(PLUS,  0, 1, 99); // v[101] = 1;
	ret.emplace_back(CMP,  98, 99, 101); // v[101] = 1;

	repfT(i, 2, 11) {
		ret.emplace_back(PLUS, 101, 100 + i - 1, 100 + i); // v[102]= 2; ...;  v[111]= 11;
	}
	ret.emplace_back(CMP, 5, 0, 10);
	ret.emplace_back(CMP, 5, 1, 11);

	repfT(i, 0, 10) {
		repfT(j, 0, 10) {
			ret.emplace_back(CMP, 100 + i, 0, 5);
			ret.emplace_back(CMP, 100 + j, 1, 6);

			ret.emplace_back(PLUS, 5, 6, 3);
			ret.emplace_back(PLUS, 3, 10, 3);
			ret.emplace_back(PLUS, 3, 11, 3);


			ret.emplace_back(CMP, 103, 3, 3);
			ret.emplace_back(PLUS, 2, 3, 2);
		}
	}
	return ret;
}


int main() {

	const auto ret = build();

	{
		cout << ret.size() << endl;
		for (const auto z : ret) {
			cout << (z.op == CMP ? "<" : "+") << " " << z.a << " " << z.b << " " << z.z << endl;
		}
		return 0;
	}

	//test(ret, 0, 5, true); return 0;


	rep(i, 11) rep(j, 11) {
		auto r = test(ret, i, j);
		if (!r.first) {
			printf("%d + %d != %lld\n", i, j, r.second);
		}
	}
	printf("FIN!\n");
	return 0;

}

