void apply(vl& v, array<int, 4> c) {
  if (c[0]) {
    v[c[3]] = v[c[1]] < v[c[2]];
  } else {
    v[c[3]] = v[c[1]] + v[c[2]];
    assert((ull)v[c[3]] <= M && v[c[3]] >= 0);
    if (c[3] == opand) assert(v[c[3]] >= 0 && v[c[3]] <= 2);
  }
}

void addand(int i, int j, int k) {
