}

void mulone(int a, int x, int k) {
  cmd.push_back({0, zero, zero, summulone});
  cmd.push_back({0, zero, zero, k});
  for (int t = pwdec.size() - 1; t >= 0; --t) {
    cmd.push_back({0, summulone, pwdec[t], summulone1});
    cmd.push_back({1, summulone1, a, summulone2});
