vector<Mem> GetBinary(Mem a)
{
    Mem aPlusOne;
    Sum(a, one, aPlusOne);
    Mem b;
    vector<Mem> bin(30);
    Mem pw;
    Mem sumBPw;
    Mem curDigit;
    for (int i = 29; i >= 0; --i)
    {
        Sum(zero, one, pw);
        for (int j = 0; j < i; ++j) Sum(pw, pw, pw);
        Sum(pw, b, sumBPw);
        Less(sumBPw, aPlusOne, curDigit);
        for (int j = 0; j < i; ++j) Sum(curDigit, curDigit, curDigit);
        Less(zero, curDigit, bin[i]);
        Sum(b, curDigit, b);
    }
    return bin;
}
int main()
{
