    cin.tie(0);
    Mem p, q;
    Less(one, A, p);
    Less(one, B, q);
    Sum(p, q, p);
    Less(zero, p, one);

    vector<Mem> a = GetBinary(A);
    vector<Mem> b = GetBinary(B);
    Mem x, y, z;
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
        {
            Less(zero, a[i], x);
            Less(zero, b[j], y);
            Sum(x, y, z);
            Less(one, z, z);
            for (int k = 0; k < i + j; ++k)
                Sum(z, z, z);
            Sum(ans, z, ans);
        }
    cout << sz << '\n' << output.str();
}

