// 300番台使用
void multiply(int i, int j, lint X)
{
    // A[j] = A[i] * X
    reset(300);
    add(300, i, 300);
    REP(d, 60)
    {
        add(300 + d, 300 + d, 300 + d + 1);
        if (1LL << d > X) break;
    }

    reset(j);
    REP(d, 60) if ((X >> d) & 1) add(300 + d, j, j);
}

void copy(int i, int j)
{
    if (i == j) return;
    reset(j);
    add(i, j, j);
}


