void subtract(int i, int j, int ret)
{
    // A[k] <- A[i] - A[j]
    int rettmp = 93;
    reset(rettmp);
    int tmp = 90, cum = 91;
    reset(cum);
    IREP(d, 32)
    {
        add(cum, j, tmp);
        add(tmp, 100 + d, tmp);
        compare(tmp, i, 92);
        multiply(92, 92, 1LL << d);
        add(92, cum, cum);
    }
    copy(cum, ret);
}

