    return bits;
  };

  auto abits = split_to_bits(A);
  auto bbits = split_to_bits(B);

  for (int i = 0; i < (int)pow2.size(); ++i) {
    for (int j = 0; j < (int)pow2.size(); ++j) {
      ops.push_back({LESS, abits[i], ONE, tmp1});
      ops.push_back({LESS, bbits[j], ONE, tmp2});
      ops.push_back({PLUS, tmp1, tmp2, tmp3});
      ops.push_back({LESS, tmp3, ONE, tmp4});
      for (int k = 0; k < i + j; ++k) {
        ops.push_back({PLUS, tmp4, tmp4, tmp4});
      }
      ops.push_back({PLUS, RES, tmp4, RES});
    }
  }

  return ops;
}

#ifdef DBG1
void run(const vector<Op> &ops, ll A, ll B) {
  vector<ll> regs(200000);
  regs[0] = A;
  regs[1] = B;
  for (const auto op : ops) {
    if (op.type == PLUS) {
      regs[op.k] = regs[op.i] + regs[op.j];
      printf("regs[%d] = regs[%d] + regs[%d]\n", op.i, op.j, op.k);
    } else if (op.type == LESS) {
      regs[op.k] = (regs[op.i] < regs[op.j] ? 1 : 0);
      printf("regs[%d] = regs[%d] < regs[%d]\n", op.i, op.j, op.k);
    } else {
      assert(0);
    }
    for (int i = 0; i < 100; ++i) {
      printf("%lld ", regs[i]);
    }
    printf("\n");
  }
  dbg("ops count %d\n", (int)ops.size());
  assert(regs[2] == A * B);
}
#endif

