#define charcters 26
struct stringtree
{
	stringtree* sons[charcters];
	stringtree* father;
	int have[charcters];
	int num = 0;
	static int func(char a) {
		return a - 'a';
	}
	stringtree(stringtree* f) {
		num = 0;
		fori(i, charcters) {
			sons[i] = NULL;
			have[i] = 0;
		}
		father = f;
	}
	stringtree* add(int p, string& x) {
		if (x.size() == p) {
			num++;
			return this;
		}
		if (sons[func(x[p])] == NULL) {
			sons[func(x[p])] = new stringtree(this);
		}
		num++;
		return sons[func(x[p])]->add(p + 1, x);
	}
	stringtree* add(string x) {
		return add(0, x);
	}
	veci find(int p, string& x) {
		if (p == x.size()) {
			veci r;
			if (num) {
				r.push_back(p);
			}
			return r;
		}
		veci r;
		if (sons[func(x[p])] != NULL) {
			r = sons[func(x[p])]->find(p + 1, x);
		}
		if (num) {
			r.push_back(p);
		}
		return r;
	}
	veci find(string x) {
		return find(0, x);
	}
	void completeserch() {
		fori(i, charcters) {
			if (sons[i] == NULL) {
				con
			}
			sons[i]->completeserch();
			fori(j, charcters) {
				if (j != i) {
					have[j] += sons[i]->have[j];
				}
			}
			have[i] += sons[i]->num;
		}
	}
};
