int main(){
    using namespace std;

    constexpr unsigned long N{200000}, register_length{100}, reg{N - register_length + 1}, one_reg{reg - 1};

    unsigned long cnt{0};
    vector<unsigned long> sim(N);
    const auto& cmp = [&cnt, &sim](unsigned long i, unsigned long j, unsigned long k) -> void {
        cout << "< " << i << " " << j << " " << k << " ";
        ++cnt;
        sim[k] = static_cast<unsigned long>(sim[i] < sim[j]);
    };
    const auto& add = [&cnt, &sim](unsigned long i, unsigned long j, unsigned long k) -> void {
        cout << "+ " << i << " " << j << " " << k << " ";
        ++cnt;
        sim[k] = sim[i] + sim[j];
    };
    const auto& set_one = [&cmp, &add]() -> void {
        add(0, 1, one_reg);
        cmp(2, one_reg, one_reg);
    };
    const auto& bit_and_add = [&cmp, &add](unsigned long i, unsigned long j, unsigned long k) -> void {
        add(i, j, reg);
        cmp(one_reg, reg, reg + 1);
        add(k, reg + 1, k);
    };
    const auto& binary_mul = [&bit_and_add](unsigned long i, unsigned long i_len, unsigned long j, unsigned long j_len, unsigned long k) -> void {
        for(unsigned long i_ofs{0}; i_ofs < i_len; ++i_ofs)for(unsigned long j_ofs{0}; j_ofs < j_len; ++j_ofs)bit_and_add(i + i_ofs, j + j_ofs, k + i_ofs + j_ofs);
    };
    const auto& bin_to_int = [&add](unsigned long beg, unsigned long len, unsigned long k) -> void {
        for(unsigned long i{len}; i--; ) {
            if(i + 1 != len)add(k, k, k);
            add(beg + i, k, k);
        }
    };
    const auto& zero_clear = [&cmp](unsigned long i) -> void {
        cmp(i, i, i);
    };
    const auto& one_clear = [&cmp](unsigned long i) -> void {
        cmp(2, one_reg, i);
    };
    const auto& bit_shift = [&add](unsigned long i, unsigned long s) -> void {
        for(unsigned long itr{0}; itr < s; ++itr)add(i, i, i);
    };
    const auto& int_to_bin = [&sim, &bin_to_int, &bit_shift, &zero_clear, &one_clear, &cmp](unsigned long idx, unsigned long i, unsigned long len) -> void {
        one_clear(reg + 2);
        for(unsigned long itr{1}; itr <= len; ++itr){
            zero_clear(reg);
            one_clear(i + len - itr);
            bin_to_int(i + len - itr, itr, reg);
            bit_shift(reg, len - itr);
            cmp(idx, reg, reg + 1);
            cmp(reg + 1, reg + 2, i + len - itr);
        }
    };

    cout << 5733 << endl;
    sim[0] = 100;
    sim[1] = 1987;
    set_one();
    int_to_bin(0, 100, 30);
    int_to_bin(1, 200, 30);
    binary_mul(100, 30, 200, 30, 300);
    bin_to_int(300, 60, 2);
    cerr << sim[2] << " : " << cnt << endl;
    return 0;
}

