struct query {
	char c;
	ll x, y, z;
};

int solve(vector<query> q, int s, int t) {
	vector<ll> a(70000);
	a[0] = s, a[1] = t;
	for (auto i : q) {
		if (i.c == '<') {
			if (a[i.x] < a[i.y]) a[i.z] = 1;
			else a[i.z] = 0;
		}
		else {
			a[i.z] = a[i.x] + a[i.y];
		}
	}
	return a[2];
}

