int ONE = -1;
vector<int> PWS;

vector<int> make_bits(int POS) {
	int plus_one = op(0, POS, ONE);
	vector<int> bits(32);
	int cur = op(0, pnt, pnt);
	for (int i = 31; i >= 0; i--) {
		int cur_add = op(0, cur, PWS[i]);
		int cur_less = op(1, cur_add, plus_one);
		bits[i] = cur_less;
		for (int j = 0; j < i; j++) {
			cur_less = op(0, cur_less, cur_less);
		}
		cur = op(0, cur, cur_less);
	}
	return bits;
}

