			add(r[i+1],r[i+1],r[i+1]);
			add(r[i+1],r[i],r[i]);
			add(s[i+1],s[i+1],s[i+1]);
			add(s[i+1],s[i],s[i]);
		}
	}
	add(c,r[0],c);
