const int N = 200000;

const int Z = N - 2;
const int O = N - 1;

vector<tuple<char, int, int, int>> vv;

void ac(int x, int y, int z) {
	vv.emplace_back('<', x, y, z);
}

void ap(int x, int y, int z) {
	vv.emplace_back('+', x, y, z);
}

void print() {
	cout << vv.size() << "\n";
	for (auto x : vv) {
		auto [a, b, c, d] = x;
		cout << a << " " << b << " " << c << " " << d << "\n";
	}
}

void check(ll a, ll b) {
	vector<ll> x(N);
	x[0] = a;
	x[1] = b;
	for (auto t : vv) {
		auto [a, b, c, d] = t;
		if (a == '<') {
			x[d] = (x[b] < x[c]);
		} else {
			x[d] = (x[b] + x[c]);
		}
	}
	assert(x[2] == a * b);
	cerr << a << " " << b << ": OK!\n";
}

random_device rd;
void test() {
	mt19937 rnd(rd());
	for (int i = 0; i < 1000; ++i) {
		int x = rnd() % 1000000000;
		int y = rnd() % 1000000000;
		check(x, y);
	}
}

const int A[2] = {100, 200};
const int CUR = 50;
const int TMP = 100000;

void pw2(int base, int x, int p) {
	ap(Z, base, x);
	for (int i = 0; i < p; ++i) {
		ap(x, x, x);
	}
}

void neg(int x) {
	ac(x, O, x);
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cout.setf(ios::fixed), cout.precision(20);

	// create 0, 1 in the end
	ac(2, 0, Z);
	ac(2, 1, O);
	ap(Z, O, O);
	ac(Z - 1, Z - 2, Z);
	ac(Z, O, O);

	for (int c : {0, 1}) {
		ac(Z, Z, CUR);
		for (int i = 29; i >= 0; --i) {
			pw2(O, CUR + 1, i);
			ap(CUR, CUR + 1, CUR + 2);

			ac(c, CUR + 2, CUR + 2);
			neg(CUR + 2);
			ap(Z, CUR + 2, A[c] + i);

			pw2(CUR + 2, CUR + 1, i);
			ap(CUR, CUR + 1, CUR);
		}
	}

	for (int i = 0; i <= 29; ++i) {
		for (int j = 0; j <= 29; ++j) {
			ap(A[0] + i, A[1] + j, TMP);
			ac(O, TMP, TMP);
			pw2(TMP, TMP, i + j);
			ap(2, TMP, 2);
		}
	}

	print();
	//test();
	return 0;
}

