void createp2() {
  add(0, 1, 3);
  comp(2, 3, 4);
  cnt = 4;
  pw2[0] = cnt;
  for (int i = 1; i < LG; i++) {
    pw2[i] = ++cnt;
    add(pw2[i-1], pw2[i-1], pw2[i]);
  }
}

void shift(int i, int it) {
  add(i, cnt+1, cnt+1); ++cnt;
  for (int j = 1; j <= it; j++) {
    add(cnt, cnt, cnt+1); ++cnt;
  }
}

vector<int> check;

vector<int> find_bin(int i) {
  vector<int> ret(LG, 0);
  int lst = ++cnt;
  add(i, pw2[0], lst); i = lst;
  // check.push_back(lst);
  lst = ++cnt;
  for (int it = LG-1; it >= 0; it--) {
    add(lst, pw2[it], ++cnt); // lst + (1 << it)
    comp(cnt, i, cnt+1); // lst + (1 << it) < i
    ret[it] = ++cnt;
    shift(ret[it], it);
    add(lst, cnt, cnt+1); // lst += 1 << it
    lst = ++cnt;
  }
  return ret;
}

void mul(int i, int j) {
  comp(i, pw2[0], ++cnt);
  comp(cnt, j, cnt+1); ++cnt;
}

