            for (int l = K; l > j; l--){
                add(q[i][l], k, k, 0);
            }
            for (int l = 0; l < j; l++){
                add(p[l], k, k, 0);
            }
            cmp(k, i, k + 1, 0);
            for (int l = 0; l < j; l++){
                add(k + 1, k + 1, k + 1, 0);
            }
            q[i][j] = k + 1;
            k += 2;
        }
    }
    for (int i = 0; i < K; i++){
        for (int j = 0; j < K; j++){
            int p1 = q[0][i];
            int p2 = q[1][j];
            cmp(k, p1, k +  1, 0);
            cmp(k, p2, k + 2, 0);
            cmp(k + 1, k + 2, k + 3, 0);
            cmp(k + 2, k + 1, k + 4, 0);
            cmp(k + 1, p[0], k + 5, 0);
            cmp(k + 2, p[0], k + 6, 0);
            add(k + 3, k + 4, k + 7, 0);
            add(k + 7, k + 5, k + 7, 0);
            add(k + 7, k + 6, k + 7, 0);
            add(k + 7, k + 7, k + 7, 0);
            cmp(k + 7, p[0], k + 7, 0);
            for (int l = 0; l < i + j; l++){
                add(k + 7, k + 7, k + 7, 0);
            }
            add(k + 7, 2, 2, 0);
            k += 8;
        }
    }
}

