const int ZERO = 100'000;
const int ONE = 100'001;
const int BASE = 100;
const int N = 200'010;
// ZERO -> const 0, ONE -> const 1
const int BIT = 5;
const int TMP = 1'000;

struct op{
    int type;
    int i, j, k;
};

int a[N];
std::vector<op> ans;

void add(int i, int j, int k){
    a[k] = a[i] + a[j];
    ans.push_back({0, i, j, k});
}

void compare(int i, int j, int k){
    a[k] = a[i] < a[j];
    ans.push_back({1, i, j, k});
}

void copy(int src, int dst){
    add(src, ZERO, dst);
}

int getbit(int bit){
    return BASE + BIT + bit;
}

void mult(int aa, int b){
    copy(ZERO, TMP);
    for (int i = 0; i <= 110; ++ i){
        compare(TMP, b, TMP + 1);
        add(TMP + 1, aa, TMP + 1);
        compare(ONE, TMP + 1, TMP + 1);
        add(TMP, TMP + 1, TMP);
    }
}

int main(){
    // scanf("%d%d", &a[0], &a[1]);
    add(0, 1, TMP);
    compare(ZERO, TMP, ONE);
    copy(0, BASE);
    for (int i = BASE + 1; i < BASE + BIT; ++ i){
        add(i - 1, i - 1, i);
    }
    copy(ONE, BASE + BIT);
    for (int i = BASE + BIT + 1; i < BASE + 2 * BIT; ++ i){
        add(i - 1, i - 1, i);
    }
    add(1, ONE, TMP + 2);
    for (int i = BIT - 1; i >= 0; -- i){
        add(TMP + 3, getbit(i), TMP + 4);
        compare(TMP + 4, TMP + 2, TMP + 4);
        mult(TMP + 4, getbit(i));
        add(TMP + 3, TMP, TMP + 3);
        mult(TMP + 4, BASE + i);
        add(2, TMP, 2);
    }
    int num = ans.size();
    printf("%d\n", num);
    for (auto u : ans){
        printf("%c %d %d %d\n", u.type == 0 ? '+' : '<', u.i, u.j, u.k);
    }
    // printf("%d\n", a[2]);
}

