    arr[i] = sum(one, arr[i - 1]);
  }
  for (int i = 1; i <= k; i++) {
    atmost_a[i] = less(arr[i], a_plus_1);
    atmost_b[i] = less(arr[i], b_plus_1);
  }
  int ret = zero;
  for (int i = 1; i <= k; i++) {
    for (int j = 1; j <= k; j++) {
      int x = AND(atmost_a[i], atmost_b[j]);
      ret = sum(ret, x);
    }
  }
  sum_query(ret, zero, 2);
  cout << e.size() << '\n';
  for (auto c : e) {
    cout << c.x << ' ' << c.a << ' ' << c.b << ' ' << c.c << '\n';
  }
}

