int L = 100;

int A = 0, B = 1;
int ONE = 3;
int P2[31];

void plessy (int k, int i, int j)
{
    // k = i + j
    cout << "+ " << i << " " << j << " " << k << "\n";
}

void iffy (int k, int i, int j)
{
    cout << "? " << i << " " << j << " " << k << "\n";
}

int mm (int x)
{
    // make huge
    plessy (L, L, x);
    for (int i = 0; i < 30; i++)
        plessy (L, L, L);
    return L++;
}

int mif (int x, int y)
{
    // runs and gives you the res
    int OM = L++;
    iffy (OM, x, ONE);

    int OP = mm (OM);
    int c2 = L++;
    plessy (c2, c2, ONE);

    int yt = L++;
    plessy (yt, y, ONE);
    int res = L++;
    for (int i = 29; i >= 0; i--)
    {
        int ptest = L++;
        plessy (ptest, OP, P2[i]);
        int pr = L++;
        iffy (pr, OP, yt);
        for (int j = 0; j < i; j++)
            plessy (pr, pr, pr);
        plessy (OP, OP, pr);
        plessy (res, res, pr);
    }
    return res;
}

int main()
{
