    {
        int ptest = L++;
        plessy (ptest, rt, P2[i]);
        int pr = L++;
        iffy (pr, ptest, yt);
        int mres = mif (pr, B);
        for (int j = 0; j < i; j++)
        {
            plessy (mres, mres, mres);
            plessy (pr, pr, pr);
        }
        plessy (rt, rt, pr);
        plessy (2, 2, mres);
    }
}

