#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using PII = pair<int, int>;
using VI = vector<int>;

enum Op { ADD = 10, LT = 20 };
string OpNames[] = {"+", "<"};

struct Inst {
  Op op;
  int lhs, rhs, res; // a[res] = op(a[lhs], a[rhs])

  Inst() {}
  Inst(Op op, int lhs, int rhs, int res)
  : op(op), lhs(lhs), rhs(rhs), res(res) {}
};

ostream& operator<<(ostream& out, const Inst& inst) {
  return out << OpNames[inst.op] << ' '
             << inst.lhs << ' ' << inst.rhs << ' ' << inst.res;
}

using Code = vector<Inst>;

const int N = 200;
int mem[N];
bool verify(const Code& code, int a, int b) {
  memset(mem, 0, sizeof mem);
  mem[0] = a;
  mem[1] = b;

  for (const auto inst: code) {
    if (inst.op == ADD) {
      mem[inst.res] = mem[inst.lhs] + mem[inst.rhs];
    } else if (inst.op == LT) {
      mem[inst.res] = mem[inst.lhs] < mem[inst.rhs] ? 1 : 0;
    } else {
      assert("inst.op is not valid" && false);
    }
  }

  return mem[2] == a * b;
}

void test(const Code& code) {
  assert(code.size() <= 200'000u);
  int total = 0, passed = 0;
  for (int a = 0; a <= 10; a++) {
    for (int b = 0; b <= 10; b++) {
      total++;
      if (!verify(code, a, b)) {
        cerr << "failed at a=" << a << ", b=" << b << endl;
      } else {
        passed++;
      }
    }
  }
  cerr << "Passed: " << passed << '/' << total << endl;
  assert(passed == total);
}

