	//X[i]=1<<(i-3);(3to2*T+2)
	repn(i, 2*T-1) {
		pl(2 + i, 2 + i, 3 + i);
	}

	rep(j, 2) {
		ll a = j;
		ll now = 2 * T + 2 + 1 + j * (T + 2);
		ll see = 2 * T + 2 + 2 + j * (T + 2);

		pl(a, 3, a);//aに1たす
		repn(i, T) {
			ll j= T + 3 - i;
			pl(now, j, see);

			hi(see, a, see + i);//i番目の桁決定
			hi(1000, see + i, 2);
			rep(j, T-i) { pl(2, 2, 2); }
			pl(2, now, now);
		}
	}

	hi(2, 1000, 2);

	rep(i, T)rep(j, T) {
		ll k = 3 * T + 4 - i;
		ll l = 4 * T + 6 - j;

		ll p = (i + j) + 3;
		pl(k, l, 0);
		hi(3, 0, 0);

		rep(j, p-3) { pl(0, 0, 0); }
		pl(2, 0, 2);
	}

	cout << X[2] << endl;
}

