inline void addPw(int x, int y, int z){
	Array tmp(2);
	int p = 0, q = 1;
	add(tmp[p], tmp[p], y); // tmp[q] = 0;
	FOR(i, 0, z){
		comp(tmp[q], tmp[q], tmp[q]); // tmp[q] = 0;
		add(tmp[q], tmp[p], tmp[p]); // tmp[q] = 2tmp[p];
		swap(p, q);
	}
	add(x, x, tmp[0]); // x[0] += tmp[0];
	return;
}

inline void toBin(Array &dec, Array &bin){
	Array tmp(2);
	int x = 0, y = 1;
	for(int i = logx - 1; i >= 0; --i){
		add(tmp[x], tmp[y], pw[i]); // tmp[x] = tmp[y] + pw[i];
		comp(bin[i], dec[0], tmp[x]); // bin[i] = (dec < pw) ? 1 : 0;
		rev(bin[i]); // bin[i] = !bin[i];
		addPw(tmp[y], bin[i], i); // tmp[y] += (bin[i] * 2^i)
	}
	return;
}

