int sum(int i, int j, int k = -1) {
	int p = (k==-1 ? new_sp() : k);
	a[p] = a[i] + a[j];
	cout << "+ " << i << ' ' << j << ' ' << p << endl;
	return p;
}
int cmp(int i, int j, int k = -1) {
	int p = (k==-1 ? new_sp() : k);
	a[p] = a[i] < a[j];
	cout << "< " << i << ' ' << j << ' ' << p << endl;
	return p;
}
void mkp2() {
	p2[0] = sum(0, 1);
	cmp(z, p2[0], p2[0]);
	for (int i = 1;i < maxk;++i)
		p2[i] = sum(p2[i-1], p2[i-1]);
}
void mul01(int i, int j, int k) {
	sum(i, j, gar[0]);
	cmp(p2[0], gar[0], k);
}
void clear(int i) {
	cmp(i, i, i);
}
void up(int pos, int t) {
	while (t--) sum(pos, pos, pos);
}
void decomp(int v, int* pos) {
	int csum = gar[1];
	clear(csum);
	for (int i = maxk-1;i >= 0;--i) {
		int asum = sum(p2[i], csum), cp = sum(p2[0], v);
		pos[i] = cmp(asum, cp);
		sum(pos[i], z, gar[2]);
		up(gar[2], i);
		sum(csum, gar[2], csum);
	}
