	for (int i = 0;i < maxk;++i) {
		for (int j = 0;j <= i;++j) {
			int x = j, y = i-j;
			mul01(pos[0][x], pos[1][y], G);
			up(G, i);
			sum(To, G, To);
		}
	}
	clear(2);
