using namespace std;

typedef long long LL;

const int N=200000,C=30;

struct operate{
  int opt,x,y,z;
  operate(int Opt=0,int X=0,int Y=0,int Z=0){opt=Opt;x=X;y=Y;z=Z;}
}ans[N+9];
int ca,cp;

void Add_ans(int opt,int x,int y,int z){ans[++ca]=operate(opt,x,y,z);}

int pw[C+9];

void Get_pw(){
  Add_ans(1,0,3,3);
  Add_ans(1,1,3,3);
  Add_ans(1,3,3,3);
  Add_ans(0,0,3,3);
  pw[0]=cp=3;
  for (int i=1;i<C;++i) Add_ans(1,cp,cp,pw[i]=cp+1),++cp;
}

int bit[2][C+9];

void Get_bit(int id){
  Add_ans(1,id,pw[0],id);
  int sum=++cp;
  for (int i=C-1;i>=0;--i){
	int t=++cp;
	Add_ans(1,sum,pw[i],t);
	Add_ans(0,t,id,t);
	bit[id][i]=t;
	++cp;Add_ans(1,cp,t,cp);
	for (int j=1;j<=i;++j) Add_ans(1,cp,cp,cp);
	Add_ans(1,sum,cp,sum);
  }
}

void Get_mul(){
  for (int i=0;i<C;++i)
	for (int j=0;j<C;++j){
	  int t=++cp;
	  Add_ans(1,bit[0][i],bit[1][j],t);
	  Add_ans(0,pw[0],t,t);
	  for (int k=1;k<=i+j;++k) Add_ans(1,t,t,t);
	  Add_ans(1,2,t,2);
	}
}

void work(){
  Get_pw();
  Get_bit(0);
  Get_bit(1);
  Get_mul();
}

void outo(){
  printf("%d\n",ca);
  for (int i=1;i<=ca;++i)
	printf("%c %d %d %d\n",ans[i].opt?'+':'<',ans[i].x,ans[i].y,ans[i].z);
}

int main(){
  work();
  outo();
