struct operation
{
    int type; // 0 = sum, 1 = compare
    int i, j, k;

    operation() = default;
};

const int N = 2e5;
const int Q = 2e5;

typedef unsigned long long ull;

const ull V = 1e19;

ull a[N];

int test(int x, int y, const vector<operation>& v)
{
    memset(a, 0, sizeof(a));
    a[0] = x;
    a[1] = y;
    for (const auto& t : v)
    {
        ull ai = a[t.i];
        ull aj = a[t.j];
        ull res;
        if (t.type == 0)
            res = ai + aj;
        else
            res = (ai < aj);
        if (res > V)
            return -2;
        a[t.k] = res;
    }
    if (a[2] != (ull)x * (ull)y)
        return -1;
    return 1;
}

int check_id(int x, int y, const vector<operation>& v, int id)
{
    memset(a, 0, sizeof(a));
    a[0] = x;
    a[1] = y;
    for (const auto& t : v)
    {
        ull ai = a[t.i];
        ull aj = a[t.j];
        ull res;
        if (t.type == 0)
            res = ai + aj;
        else
            res = (ai < aj);
        if (res > V)
            return -2;
        a[t.k] = res;
    }
    return a[id];
}

