void run(V<int>& v, V<std::string> c) {
	for (auto s : c) {
		std::stringstream ss(s);
		char op;
		ss >> op;
		int i, j, k;
		ss >> i >> j >> k;
		if (op == '+') v[k] = v[i] + v[j];
		else v[k] = v[i] < v[j];
	}
}

