	using P = std::tuple<char, int, int, int>;
	std::vector<P> ans;
									// 0 | 1 | 2 |   3   | 4 | 5
	ans.push_back(P{'+', 0, 1, 3});
	ans.push_back(P{'<', 100, 3, 3});
	ans.push_back(P{'+', 0, 5, 5}); // A | B | 0 |   1   | 0 | A

	// A or B = 0 のとき v[0] = v[1] = 0 にする処理
	ans.push_back(P{'<', 100, 0, 20});
	ans.push_back(P{'<', 100, 1, 21});
	ans.push_back(P{'+', 20, 21, 20});
	ans.push_back(P{'<', 100, 20, 20}); // v[20]: A 用
	ans.push_back(P{'+', 100, 20, 21}); // v[21]: B 用
	for(int i = 0; i < 11; i++) {
		ans.push_back(P{'+', 20, 22, 22});
		ans.push_back(P{'<', 22, 0, 20});
		ans.push_back(P{'+', 21, 23, 23});
		ans.push_back(P{'+', 23, 1, 21});
	}
	ans.push_back(P{'+', 100, 22, 0});
	ans.push_back(P{'+', 100, 23, 1});
	ans.push_back(P{'+', 100, 100, 20});
	ans.push_back(P{'+', 100, 100, 21});
	ans.push_back(P{'+', 100, 100, 22});
	ans.push_back(P{'+', 100, 100, 23});
	// 終わり

	for(int i = 0; i < 20; i++) {
		ans.push_back(P{'+', 5, 2, 2}); // V[2] += (A or 0)
		ans.push_back(P{'+', 3, 4, 4}); // V[4] += 1
		ans.push_back(P{'+', 100, 100, 5}); // V[5] <- 0

		{ // V[4] が B 未満のときのみ V[5] に A を作る
			ans.push_back(P{'<', 4, 1, 6}); // V[6] <- (cnt < B)
			ans.push_back(P{'+', 3, 100, 7}); // V[7] <- 1
			for(int i = 0; i < 11; i++) {
				ans.push_back(P{'+', 6, 5, 5}); // V[5]++
				ans.push_back(P{'+', 3, 7, 7}); // V[7]++
				ans.push_back(P{'<', 0, 7, 8}); // V[8] <- (A < V[7])
				ans.push_back(P{'<', 8, 6, 6}); // V[6] <- (V[8] < V[6])
			}
			ans.push_back(P{'+', 100, 100, 6});
			ans.push_back(P{'+', 100, 100, 7});
		}
	}

	// output
	printf("%d\n", ans.size());
	for(auto [c, x, y, z]: ans) printf("%c %d %d %d\n", c, x, y, z);
	return 0;
}

#include<bits/stdc++.h>

int main() {
	using namespace std;
	ios_base::sync_with_stdio(false), cin.tie(nullptr);
	const __int128_t TEST_A = 1e9;
	const __int128_t TEST_B = 1e9;
	vector<__int128_t> regs(200000, 0);
	regs[0] = TEST_A;
	regs[1] = TEST_B;

	vector<tuple<char, int, int, int>> ops;
	auto plus = [&](int i, int j, int k) {
		regs[k] = regs[i] + regs[j];
		ops.emplace_back('+', i, j, k);
	};
	auto less = [&](int i, int j, int k) {
		regs[k] = regs[i] < regs[j];
		ops.emplace_back('<', i, j, k);
	};

	const int A[2] = {0, 1};
	const int R = 2;
	const int ZERO = 3;
	const int ONE = 4;
	plus(A[0], A[1], ONE);
	less(ZERO, ONE, ONE);

	auto neg = [&](int i, int j) {
		less(i, ONE, j);
	};

	auto either = [&](int i, int j, int k) {
		plus(i, j, k);
		less(ZERO, k, k);
	};
	const int SCRATCH1 = 5;
	const int SCRATCH2 = 6;
	auto both = [&](int i, int j, int k) {
		neg(i, SCRATCH1);
		neg(j, SCRATCH2);
		either(SCRATCH1, SCRATCH2, k);
		neg(k, k);
	};

	const int LG = 30;

	const int A_BITS[2] = {1000, 2000};
	const int SCRATCH = 10000;
	for (int z = 0; z < 2; z++) {
		plus(ZERO, ZERO, SCRATCH);
		for (int i = LG-1; i >= 0; i--) {
			plus(SCRATCH, SCRATCH, SCRATCH);
			plus(SCRATCH, ZERO, A_BITS[z]+i);
			for (int j = 0; j < i; j++) {
				plus(A_BITS[z]+i, A_BITS[z]+i, A_BITS[z]+i);
				plus(A_BITS[z]+i, ONE, A_BITS[z]+i);
			}
			less(A_BITS[z]+i, A[z], A_BITS[z]+i);
			plus(SCRATCH, A_BITS[z]+i, SCRATCH);
		}
	}

	const int R_BITS = 6000;
	for (int i = 0; i < LG; i++) {
		for (int j = 0; j < LG; j++) {
			both(A_BITS[0]+i, A_BITS[1]+j, SCRATCH);
			plus(R_BITS+i+j, SCRATCH, R_BITS+i+j);
		}
	}
	for (int i = 2*(LG-1); i >= 0; i--) {
		plus(R, R, R);
		plus(R, R_BITS+i, R);
	}

	assert(regs[2] == TEST_A * TEST_B);

	cout << ops.size() << '\n';
	for (auto [op, i, j, k] : ops) {
		cout << op << ' ' << i << ' ' << j << ' ' << k << '\n';
	}

	return 0;
}

