  for(int i=0;i<(int)buf.size();i++) buf[i]=i+3+mul.size();
  for(int i=0;i<(int)num.size();i++) num[i]=i+3+mul.size()+buf.size();

  ans.emplace_back(add(A,B,S));
  ans.emplace_back(cmp(Z,S,O));

  for(int k=1;k<=11;k++)
    ans.emplace_back(add(num[k-1],O,num[k]));

  // A >= x and B >= y -> make 1
  // A > x - 1 and B > y - 1
  // 1 < ((A > x - 1) + (B > y - 1))

  for(int x=1;x<=10;x++){
    for(int y=1;y<=10;y++){
      ans.emplace_back(cmp(A,A,buf[0]));
      ans.emplace_back(cmp(A,A,buf[1]));
      ans.emplace_back(cmp(A,A,buf[2]));
      ans.emplace_back(cmp(A,A,buf[3]));

      ans.emplace_back(cmp(num[x-1],A,buf[0]));
      ans.emplace_back(cmp(num[y-1],B,buf[1]));

      ans.emplace_back(add(buf[0],buf[1],buf[2]));
      ans.emplace_back(cmp(O,buf[2],buf[3]));

      ans.emplace_back(add(Z,buf[3],mul[(x-1)*10+(y-1)]));
    }
  }

  for(int i=0;i<(int)mul.size();i++)
    ans.emplace_back(add(C,mul[i],C));

  if(0){
    int a,b;
    cin>>a>>b;
    solve(ans,a,b);
    return 0;
  }

  if(true){
    for(int a=0;a<=10;a++)
      for(int b=0;b<=10;b++)
        assert(solve(ans,a,b)==a*b);
  }

  cout<<ans.size()<<endl;
  for(string s:ans) cout<<s<<endl;
  return 0;
}

