using namespace std;

int tot = 199999, cnt = 0;

int Operator1(int x, int y, int z = tot) {
	cnt++;
	if (z == tot) tot--;
	cout << "< " << x << " " << y << " " << z << endl;
	return z;
}

int Operator2(int x, int y, int z = tot) {
	cnt++;
	if (z == tot) tot--;
	cout << "+ " << x << " " << y << " " << z << endl;
	return z;
}

int A = 0, B = 1, zero = 3, ONE;

int get_A(int one, int A) {
	vector <int> pw; pw.push_back(one);
	for (int i = 1; i < 30; i++) {
		int x = Operator2(pw.back(), pw.back());
		pw.push_back(x);
	}
	int ans = tot--;
	for (int i = 29; i >= 0; i--) {
		int x = Operator2(pw[i], ans);
		x = Operator1(x, A);
		x = Operator2(x, one);
		x = Operator1(ONE, x);
		for (int j = 0; j < i; j++) {
			Operator2(x, x, x);
		}
		Operator2(ans, x, ans);
	}
	int x = Operator1(zero, A);
	x = Operator2(x, one), x = Operator1(ONE, x);
	Operator2(x, ans, ans);
	return ans;
}

int main () {
//	freopen("code.lan", "w", stdout);
	ONE = Operator1(zero, Operator2(A, B));
	vector <int> pw;
	int lst = ONE; pw.push_back(ONE);
	for (int i = 1; i <= 30; i++) {
		int x = Operator2(lst, lst);
		pw.push_back(x), lst = x;
	}
	int cur = tot--, ans = 2;
	for (int i = 29; i >= 0; i--) {
		int x = Operator2(cur, pw[i]);
		x = Operator1(x, B);
		int y = get_A(x, A);
		for (int j = 0; j < i; j++) {
			Operator2(x, x, x);
			Operator2(y, y, y);
		}
		Operator2(cur, x, cur), Operator2(ans, y, ans);
	}
	int x = get_A(Operator1(zero, B), A);
	Operator2(ans, x, ans);
	return 0;
}

