void reset(int a)
{
    set(a,zero);
}

void lt(int c, int a, int b)
{
    printf("< %d %d %d\n", a, b, c);
}

void add(int c, int a, int b)
{
    printf("+ %d %d %d\n", a, b, c);
}

void leak(int res, int tar)
{
    int back_ebp = ebp;
    ebp = esp, esp -= 3;
    int base = esp+0, tao = esp+1, k=esp+2;
    add(tao,tar,one);
    for(int i=N-1;i>=0;--i)
    {
        set(k,one);
        for(int j=0;j<i;++j) add(k,k,k);
        int t = res + i;
        add(k,base,k);
        lt(t,k,tao);
        set(k,t);
        for(int j=0;j<i;++j) add(k,k,k);
        add(base,base,k);
    }
    esp = ebp, ebp = back_ebp;
}

void and_op(int c, int a, int b)
{
    int back_ebp = ebp;
    ebp = esp, esp -= 1;
    int k = esp;
    add(k,a,b);
    lt(c,one,k);
    esp = ebp, ebp = back_ebp;
}

void mul(int res, int a, int b)
{
    int back_ebp = ebp;
    ebp = esp, esp -= N*2+1;
    int la = esp, lb = esp+N, t=esp+N*2;
    reset(res);
    leak(la,a);
    leak(lb,b);
    for(int i=0;i<N;++i)for(int j=0;j<N;++j)
    {
        and_op(t,la+i,lb+j);
        for(int k=0;k<i+j;++k) add(t,t,t);
        add(res,res,t);
    }
    esp = ebp, ebp = back_ebp;
}

