vector<string> ans;
int mem[200];

void LT(int i, int j, int k) {
    mem[k] = mem[i] < mem[j];
    static char buf[50];
    sprintf(buf, "< %d %d %d\n", i, j, k);
    ans.push_back(buf);
}

void ADD(int i, int j, int k) {
    mem[k] = mem[i] + mem[j];
    static char buf[50];
    sprintf(buf, "+ %d %d %d\n", i, j, k);
    ans.push_back(buf);
}

void OR(int i, int j, int k) {
    assert(i != j);
    assert(i != k);
    assert(j != k);
    ADD(i, j, k);
    LT(ZERO, k, k);
}

void AND(int i, int j, int k) {
    // a[i] && a[j] -> a[k];
    assert(i != j);
    assert(i != k);
    assert(j != k);
    // a[i] <= 1;
    // a[j] <= 1;

    int tmpI = mem[i], tmpJ = mem[j];
    ADD(i, j, k);
    LT(ONE, k, k);
    assert(mem[k] == (tmpI && tmpJ));
}

