int New_Temporary_Pos() {
  static int x = 10000;
  x += 35; //each time no more than 30 position is used
  return x;
}

int Power2(int x) { return x + 2; }

int Not(int t) {
  int temp = New_Temporary_Pos();
  Comp(t, 2, temp);
  return temp;
}

int Or(int a, int b) {
  int temp = New_Temporary_Pos();
  Comp(50, a, temp); //[50] = 0
  Comp(a, b, temp + 1);
  Add(temp, temp + 1, temp);
  return temp;
}

int And(int a, int b) {
  return Not(Or(Not(a), Not(b)));
}

void AddPower(int x, int c, int k) {
  int temp = New_Temporary_Pos();
  Add(c, temp, temp);
  for (int i = 1; i <= k; ++i) {
    Add(temp, temp, temp);
  }
  Add(x, temp, x);
}

//decompose a number into 2-base representation
void Decompose(int x, int store_pos) {
  int temp_pos = New_Temporary_Pos();
  int nx = temp_pos + 1;
  Add(x, 2, nx); // [nx] = x + 1
  int pos = temp_pos + 1;
  for (int i = 29; ~i; --i) {
    Add(temp_pos, Power2(i), ++pos);
    Comp(pos, nx, ++store_pos);
    AddPower(temp_pos, store_pos, i);  // if result is 1 , temp += 2^..
  }
}

