#include <bits/stdc++.h>
using namespace std;

const int B = 32, N = 200000;
template <class T>
void read(T &x) {
	int sgn = 1;
	char ch;
	x = 0;
	for (ch = getchar(); (ch < '0' || ch > '9') && ch != '-'; ch = getchar()) ;
	if (ch == '-') ch = getchar(), sgn = -1;
	for (; '0' <= ch && ch <= '9'; ch = getchar()) x = x * 10 + ch - '0';
	x *= sgn;
}
template <class T>
void write(T x) {
	if (x < 0) putchar('-'), write(-x);
	else if (x < 10) putchar(x + '0');
	else write(x / 10), putchar(x % 10 + '0');
}

struct op {
	int ty, i, j, k;
	void print() {
		putchar(ty ? '+' : '<'), putchar(' ');
		write(i), putchar(' ');
		write(j), putchar(' ');
		write(k), putchar('\n');
	}
} ;
vector<op> ans_list; 
int cnt = 5, one = 5, pw2[B], bit1[B], bit2[B], rev1[B], rev2[B], val[B][B];

void build(int ty, int i, int j, int k) {
	op tmp = {ty, i, j, k};
	ans_list.push_back(tmp);
}
void binary() {
	int now = ++cnt;
	for (int i = B - 1; i >= 0; i--) {
		build(1, now, pw2[i], ++cnt);
		build(0, 0, cnt, cnt + 1), cnt++;
		build(0, cnt, one, cnt + 1);
		bit1[i] = ++cnt;
		for (int j = 0; j < i; j++) build(1, cnt, cnt, cnt + 1), cnt++;
		build(1, now, cnt, cnt + 1);
		now = ++cnt;
	}
	now = ++cnt;
	for (int i = B - 1; i >= 0; i--) {
		build(1, now, pw2[i], ++cnt);
		build(0, 1, cnt, cnt + 1), cnt++;
		build(0, cnt, one, cnt + 1);
		bit2[i] = ++cnt;
		for (int j = 0; j < i; j++) build(1, cnt, cnt, cnt + 1), cnt++;
		build(1, now, cnt, cnt + 1);
		now = ++cnt;
	}
}

int main() {
	build(1, 0, 1, 3);
	build(0, 4, 3, 5);
	pw2[0] = one;
	for (int i = 1; i < B; i++) {
		build(1, pw2[i - 1], pw2[i - 1], ++cnt);
		pw2[i] = cnt;
	}
	binary();
	for (int i = 0; i < B; i++) build(0, bit1[i], one, ++cnt), rev1[i] = cnt;
	for (int i = 0; i < B; i++) build(0, bit2[i], one, ++cnt), rev2[i] = cnt;
	for (int i = 0; i < B; i++) {
		for (int j = 0; j < B; j++) {
			build(0, rev1[i], rev2[j], cnt + 1);
			build(0, rev2[j], rev1[i], cnt + 2);
			build(1, rev1[i], cnt + 3, cnt + 4);
			build(1, rev2[j], cnt + 4, cnt + 5);
			build(1, cnt + 1, cnt + 5, cnt + 6);
			build(1, cnt + 2, cnt + 6, cnt + 7);
			build(0, cnt + 7, one, cnt + 8);
			cnt += 8;
			for (int k = 0; k < i + j; k++) build(1, cnt, cnt, cnt + 1), cnt++;
			val[i][j] = cnt;
		}
	}
	cnt++;
	for (int i = 0; i < B; i++) {
		for (int j = 0; j < B; j++) {
			build(1, cnt, val[i][j], cnt + 1), cnt++;
		}
	}
	build(1, cnt, cnt + 1, 2);
	write(ans_list.size()), putchar('\n');
	for (int i = 0; i < ans_list.size(); i++) ans_list[i].print();
	return 0;
}

