const int MAXN = 200000 + 5;
struct node{char ch; int x, y, z;};
vector<node>vec;
void emit(char ch, int x, int y, int z) {
    vec.push_back({ch, x, y, z});
}
bool used[MAXN];
int cnt = 1;
int newtemp() {
    while (used[cnt]) cnt++;
    used[cnt] = 1;
    return cnt;
}
const int up = 30;
int powB[32], pow2[32], p2[32];
int main() {
    int res = 2;
    used[0] = used[1] = used[2] = 1;
    int zero = newtemp(), one = newtemp();
    int A = newtemp();
    int B = newtemp(); 
    emit('+', 0, zero, A);
    emit('+', 1, zero, B);
    emit('+', zero, zero, 0);
    int AplusB = newtemp();
    emit('+', A, B, AplusB);
    emit('<', zero, AplusB, one);

    powB[0] = B;
    for (int i = 1; i <= up; i++) {
        powB[i] = newtemp();
        emit('+', powB[i - 1], powB[i - 1], powB[i]);
    }

    pow2[0] = one; 
    for (int i = 1; i <= up; i++) {
        pow2[i] = newtemp();
        emit('+', pow2[i - 1], pow2[i - 1], pow2[i]);
    }
    int cntA = newtemp(), temp = newtemp(), sig1 = newtemp(), sig2 = newtemp(), sig = newtemp();
    for (int k = up; k >= 0; k--) {

        // cntA += 2^k
        emit('+', cntA, pow2[k], temp);
        emit('<', temp, A, sig1);
        emit('<', A, temp, sig2);
        emit('+', sig2, sig2, sig2);
        emit('+', sig1, one, sig1);
        emit('<', sig2, sig1, sig);
        int v1 = newtemp(); // 2^k or 0
        emit('+', sig, zero, v1);
        for (int i = 1; i <= k; i++) emit('+', v1, v1, v1);
        emit('+', cntA, v1, cntA);

        // res += 2^k * B
        p2[0] = newtemp();
        emit('+', zero, sig, p2[0]);
        for (int i = 1; i <= up; i++) {
            p2[i] = newtemp();
            emit('+', p2[i - 1], p2[i - 1], p2[i]);
        }
        int v2 = newtemp(); // 2^k * B or 0
        int t = newtemp(), sigB1 = newtemp(), sigB2 = newtemp(), sigB = newtemp();
        for (int i = up; i >= 0; i--) {
            emit('+', v2, p2[i], t);
            emit('<', t, B, sigB1);
            emit('<', B, t, sigB2);
            emit('+', sigB1, sigB1, sigB1);
            emit('+', sigB1, one, sigB1);
            emit('<', sigB2, sigB1, sigB);
            emit('+', sigB, p2[0], sigB);
            emit('<', one, sigB, sigB);
            int vv = newtemp();
            emit('+', sigB, zero, vv);
            for (int j = 1; j <= i; j++) emit('+', vv, vv, vv);
            emit('+', v2, vv, v2);
        }
        // now v2 == B
        for (int i = 1; i <= k; i++) emit('+', v2, v2, v2);
        emit('+', res, v2, res);
    }

    printf("%d\n", (int)vec.size());
    for (auto item : vec) {
        printf("%c %d %d %d\n", item.ch, item.x, item.y, item.z);
    }
    return 0;
}

