    // cerr << "eq " << a_eq[0] << " " << b_eq[10] << endl;
    function<void(int i, int j, int k)> emit_not_and = [&](int i, int j, int k) {
        const int notj = idx;
        // not j to idx
        prog.push_back(LT(j, constant[1], notj));
        // i or j to idx
        prog.push_back(ADD(i, notj, idx));
        prog.push_back(LT(constant[0], idx, idx));
        // not idx
        prog.push_back(LT(idx, constant[1], k));
    };
    function<void(int i, int j, int k)> emit_and = [&](int i, int j, int k) {
        const int noti = idx, notj = idx + 1;
        // not j to idx
        prog.push_back(LT(i, constant[1], noti));
        prog.push_back(LT(j, constant[1], notj));
        // i or j to idx
        prog.push_back(ADD(noti, notj, idx));
        prog.push_back(LT(constant[0], idx, idx));
        // not idx
        prog.push_back(LT(idx, constant[1], k));
    };
    for (int i = 0; i <= 10; i++) {
        emit_not_and(a_lt[i], a_lt[i+1], a_eq[i]);
        emit_not_and(b_lt[i], b_lt[i+1], b_eq[i]);
    }
    int ab_eq[11][11];
    for (int i = 0; i <= 10; i++) {
        for (int j = 0; j <= 10; j++) {
            ab_eq[i][j] = idx++;
            emit_and(a_eq[i], b_eq[j], ab_eq[i][j]);
            // cerr << i << " " << j << " " << ab_eq[i][j] << endl;
        }
    }
    for (int i = 0; i <= 10; i++) {
        for (int j = 0; j <= 10; j++) {
            ab_eq[i][j] = idx++;
            emit_and(a_eq[i], b_eq[j], ab_eq[i][j]);
        }
    }
    for (int i = 0; i <= 10; i++) {
        for (int j = 0; j <= 10; j++) {
            prog.push_back(LT(constant[0], ab_eq[i][j], idx));
            for (int k = 0; k < i * j; k++)
                prog.push_back(ADD(2, idx, 2));
        }
    }
    cout << prog.size() << endl;
    for (auto &[op, i, j, k] : prog)
        cout << op << ' ' << i << ' ' << j << ' ' << k << endl;
    // for (int i = 0; i <= 10; i++) {
