inline void plus(int src1, int src2, int dst) {
	printf("+ %d %d %d\n", src1, src2, dst);
}
inline void less(int src1, int src2, int dst) {
	printf("< %d %d %d\n", src1, src2, dst);
}
void prepare() {
	idx = 5;
	for (int i = 0; i < 30; i++) {
		a[i] = ++idx;
	}
	for (int i = 0; i < 30; i++) {
		b[i] = ++idx;
	}
	for (int i = 0; i < 30; i++) {
		p[i] = ++idx;
	}
	for (int i = 0; i < 30; i++) {
		q[i] = ++idx;
	}
	one = p[0];
	zero = q[0];
	plus(0, 1, 3);
	less(0, 3, 4);
	less(1, 3, 5);
	plus(4, 5, one);
	less(zero, one, one);
	for (int i = 1; i < 30; i++) {
		plus(p[i - 1], p[i - 1], p[i]);
	}
	for (int i = 1; i < 30; i++) {
		plus(q[i - 1], p[i - 1], q[i]);
	}
}
inline void getBit(int *bit, int src) {
	int tmp = ++idx, cmp = ++idx, pow = ++idx;
	for (int i = 29; i >= 0; i--) {
		plus(tmp, q[i], cmp);
		less(cmp, src, bit[i]);
		plus(bit[i], zero, pow);
		for (int j = 0; j < i; j++) {
			plus(pow, pow, pow);
		}
		plus(tmp, pow, tmp);
	}
}
inline void calc() {
	int tmp = ++idx;
	for (int i = 0; i < 30; i++) {
		for (int j = 0; j < 30; j++) {
			plus(a[i], b[j], tmp);
			less(one, tmp, tmp);
			for (int k = 0; k < i + j; k++) {
				plus(tmp, tmp, tmp);
			}
			plus(2, tmp, 2);
		}
	}
}
