	res.push_back(string(str));
}

void addition(int x, int y, int z) {
	sprintf(str, "+ %d %d %d", x, y, z);
	res.push_back(string(str));
}

void calc(int x, int n) {
	smaller(n + 30, x, n + 30);
	rep(i, 1, 30 - 1) addition(n + 30 + (i - 1), n + 30 + (i - 1), n + 30 + i);
	rep(i, 1, 30 - 1) addition(n + 60 + (i - 1), n + 30 + (i - 1), n + 60 + i);
	int m = n + 90;
	per(i, 30 - 1, 0) {
		smaller(n + 60 + i, x, m);
		addition(n + i, m, n + i);
		rep(j, 0, i - 1) addition(m, m, m);
		addition(3, 3, m + 2);
		per(j, 30 - 1, 0) {
			addition(x, n + 30, m + 1);
			addition(m + 2, n + 30 + j, m + 3);
			addition(m + 3, m, m + 3);
			smaller(m + 3, m + 1, m + 4);
			rep(k, 0, j - 1) addition(m + 4, m + 4, m + 4);
			addition(m + 2, m + 4, m + 2);
		}
		addition(3, m + 2, x);
	}
}

void work(int n, int m, int K) {
	rep(i, 0, 30 - 1) addition(4, i + n, 4);
	rep(i, 0, 30 - 1) addition(4, i + m, 4);
	smaller(3, 4, 4);
	rep(i, 0, 30 - 1) rep(j, 0, 30 - 1) {
		addition(i + n, j + m, 5);
		smaller(4, 5, 5);
		addition(K + i + j, 5, K + i + j);
	}
	rep(i, 0, 60 - 2) {
		rep(k, 0, i - 1) addition(K + i, K + i, K + i);
		addition(2, K + i, 2);
	}
}

