using namespace std;

int tot, lg[30], a[30], b[30];
vector<tuple<char, int, int, int>> ans;

int main() {
    auto plus = [&](int i, int j, int k) {
        ans.push_back(make_tuple('+', i, j, k));
    };
    auto less = [&](int i, int j, int k) {
        ans.push_back(make_tuple('<', i, j, k));
    };
    auto shift = [&](int i, int k) { // x: x*2^k
        while (k--) plus(i, i, i);
    };
    // 2: 0; 3: 1; lg[i]: 2^i
    plus(0, 1, 3), less(2, 3, 3), tot = lg[0] = 3;
    for (int i = 1; i <= 29; i++) {
        plus(lg[i - 1], lg[i - 1], lg[i] = ++tot);
    }
    auto solve = [&](int *a, int pos) {
        plus(pos, 3, ++tot), pos = tot;
        int cur = ++tot;
        for (int i = 29; ~i; i--) {
            int tmp = ++tot;
            plus(cur, lg[i], tmp);
            less(tmp, pos, a[i] = ++tot);
            plus(tmp, 2, ++tot), tmp = ++tot;
            shift(tmp, i);
            plus(cur, tmp, cur);
        }
    };
    solve(a, 0), solve(b, 1);
    for (int i = 0; i <= 29; i++) {
        for (int j = 0; j <= 29; j++) {
            int tmp = ++tot;
            plus(a[i], b[j], tmp);
            less(3, tmp, tmp);
            shift(tmp, i + j);
            plus(2, tmp, 2);
        }
    }
    printf("%d\n", ans.size());
    for (auto p : ans) {
        printf("%c %d %d %d\n", get<0>(p), get<1>(p), get<2>(p), get<3>(p));
    }
    return 0;
}

