int alloc() {
	return tot++;
}
void add(int a, int b, int c) {
	printf("+ %d %d %d\n", a, b, c);
}
void less(int a, int b, int c) {
	printf("< %d %d %d\n", a, b, c);
}
void lsh(int a, int k) {
	while(k--) add(a, a, a);
}
int main() {
	int a=0, b=1, res=2, zero=alloc(), one=alloc();
	add(a, b, one);
	less(zero, one, one);
	up[0]=one;
	for(int i=1; i<60; ++i) up[i]=alloc();
	for(int i=0; i<30; ++i) aa[i]=alloc();
	for(int i=0; i<30; ++i) bb[i]=alloc();
	for(int i=0; i<60; ++i) cc[i]=alloc();
	int t=alloc(), tmp=alloc();
	for(int i=1; i<60; ++i) add(up[i-1], up[i-1], up[i]);
	for(int i=30; i--; ) {
		add(t, up[i], tmp);
		less(a, tmp, aa[i]);
		less(aa[i], one, aa[i]);
		add(zero, aa[i], tmp);
		lsh(tmp, i);
		add(t, tmp, t);
	}
	t=alloc();
	for(int i=30; i--; ) {
		add(t, up[i], tmp);
		less(b, tmp, bb[i]);
		less(bb[i], one, bb[i]);
		add(zero, bb[i], tmp);
		lsh(tmp, i);
		add(t, tmp, t);
	}
	for(int i=0; i<30; ++i) {
		for(int j=0; j<30; ++j) {
			add(aa[i], bb[j], tmp);
			less(one, tmp, tmp);
			add(cc[i+j], tmp, tmp);
		}
	}
	for(int i=0; i<60; ++i) {
		lsh(cc[i], i);
		add(res, cc[i], res);
	}
	return 0;
