void mult(int l1,int l2,int l3,int k){
    for (int i=0;i<=k;i++){
        for (int j=0;j<=k;j++){
            int res=i+j;
            land(l1+i,l2+j,14);
            vec.push_back(Ene(1,14,l3+res,l3+res));
        }
    }
}
void to_dec(int x,int l,int k){
    for (int i=0;i<=k;i++){
        vec.push_back(Ene(1,3,l+i,15)); //arr[15]=0+arr[l+i];
        lmv(15,i);
        vec.push_back(Ene(1,x,15,x)); //arr[x]=arr[x]+arr[15];
    }
}
void to_bin(int x,int l,int k){
    vec.push_back(Ene(1,x,N,13)); //arr[13]=1+arr[x];
    vec.push_back(Ene(1,3,3,11)); //arr[11]=0+0;
    //Position 11 saves the certain sum
    //Position 12 is used to try
    //Position 13 saves arr[x]+1
    for (int tlg=k;tlg>=0;tlg--){
        vec.push_back(Ene(1,N-tlg,11,12)); //arr[12]=arr[11]+(1<<k);
        vec.push_back(Ene(2,12,13,12)); //arr[12]=(arr[12]<arr[13]);
        vec.push_back(Ene(1,12,3,l+tlg)); //arr[l+tlg]=arr[12]+0;
        lmv(12,tlg);
        vec.push_back(Ene(1,11,12,11)); //arr[11]=arr[11]+arr[12];
    }
}
void make_pw(void){
    vec.push_back(Ene(1,0,1,N));
    vec.push_back(Ene(2,3,N,N));
    for (int i=1;i<=MXLG;i++)
        vec.push_back(Ene(1,N-i+1,N-i+1,N-i));
}
void lmv(int x,int k){
    while (k--)
        vec.push_back(Ene(1,x,x,x));
}
void land(int x,int y,int z){
    vec.push_back(Ene(1,x,y,4)); //arr[4]=arr[x]+arr[y];
    vec.push_back(Ene(2,N,4,z)); //arr[z]=(1<arr[4]);
}

io_t seto(void){
    io_t x=0;
    char ch=getchar();
    int symbol=0;
    while (!isdigit(ch))
        (ch=='-')?(symbol=1):(0),
        ch=getchar();
    while (isdigit(ch))
        x=(x*10)+(ch-'0'),
        ch=getchar();
    return (symbol)?(-x):(x);
}
void ayano(io_t x,char spliter){
    if (!x){
        putchar('0'),putchar(spliter);
        return;
    }
    if (x<0)
        putchar('-'),x=-x;
    int ren=0;
    while (x){
        io_t d=x/10;
        shin[ren++]=x-d*10;
        x=d;
    }
    while (ren--)
        putchar(shin[ren]+'0');
    putchar(spliter);
}

