struct Query {
	int i, j, k;
	char c;
	Query();
	Query(char c, int i, int j, int k) :
		c(c), i(i), j(j), k(k) {};
};

vector <Query> ans;

void add(int t, int i, int j, int k) {
	Query cur = Query(t == 0 ? '+' : '<', i, j, k);
	ans.push_back(cur);
}

int arr[N];

void apply(const Query& q) {
	if (q.c == '+')
		arr[q.k] = arr[q.i] + arr[q.j];
	else
		arr[q.k] = arr[q.j] > arr[q.i];
}

void solve() {
	int a, b;
	cin >> a >> b;
	add(1, 2, 0, 4);
	for (int i = 5; i < 13; i++)
		add(0, 4, i - 1, i);
	for (int i = 13; i < 23; i++)
		add(1, i - 10, 0, i);
	for (int i = 23; i < 32; i++) {
		for (int j = 0; j < 10; j++) {
			add(1, i, 1, 33);
			add(0, 33, i - 10, 34);
			add(1, 4, 34, 35);
			add(0, i, 35, i);
		}
		add(0, 2, i, 2);
	}
	arr[0] = a, arr[1] = b;
	cout << size(ans) << endl;
	for (auto q : ans) {
		apply(q);
		//cout << q.c << ' ' << q.i << ' ' << q.j << ' ' << q.k << endl;
	}
	cout << arr[2];
}

