vi get_binary(int i){
	int w=cmp(Z,i);
	i=add(i,w);
	int res=Z;
	vi z(30,Z);
	rep(_,30){
		vi u(30);
		int tmp=w;
		rep(k,30){
			u[k]=cmp(add(res,tmp),i);
			tmp=add(tmp,tmp);
		}
		u.pb(Z);
		rep(k,30){
			z[k]=add(z[k],u[k]=cmp(u[k+1],u[k]));
		}
		int now=Z;
		per(k,30){
			now=add(now,now);
			now=add(now,u[k]);
		}
		res=add(res,now);
	}
