  iota(begin(pw), end(pw), 4);
  res.emplace_back('<', c, ab, pw[0]);
  for (int i = 1; i < 60; ++i) {
    res.emplace_back('+', pw[i - 1], pw[i - 1], pw[i]);
  }
  int r = 199999;
  auto mul = [&](int i, int j, int k) {
    res.emplace_back('+', i, j, r);
    res.emplace_back('<', pw[0], r, k);
    res.emplace_back('<', r, r, r);
  };
  auto pw2 = [&](int i, int cond, int dst) {
    res.emplace_back('+', r, cond, dst);
    while (i--) {
      res.emplace_back('+', dst, dst, dst);
    }
  };
  auto encode = [&](int src, int dst) {
    int cnt = 1e5, sum = cnt + 1, pwi = sum + 1, srco = pwi + 1;
    res.emplace_back('+', src, pw[0], srco);
    for (int i = 60; i--; ) {
      res.emplace_back('+', cnt, pw[i], sum);
      res.emplace_back('<', sum, srco, dst + i);
      pw2(i, dst + i, pwi);
      res.emplace_back('+', cnt, pwi, cnt);
    }
    res.emplace_back('<', cnt, cnt, cnt);
    res.emplace_back('<', cnt, cnt, sum);
  };
  int s = 100, t = 200;
  encode(a, s);
  encode(b, t);
  int cur = r - 1, coeff = cur - 1;
  for (int i = 0; i < 30; ++i) {
    for (int j = 0; j < 30; ++j) {
      mul(s + i, t + j, coeff);
      pw2(i + j, coeff, cur);
      res.emplace_back('+', c, cur, c);
      res.emplace_back('<', cur, cur, cur);
      res.emplace_back('<', cur, cur, coeff);
    }
  }
  cout << size(res) << '\n';
  vector<long long> arr(2e5);
  arr[0] = 13, arr[1] = 10;
  for (auto [op, i, j, k] : res) {
    cout << op << ' ' << i << ' ' << j << ' ' << k << '\n';
    if (op == '+') {
      arr[k] = arr[i] + arr[j];
    } else {
      arr[k] = arr[i] < arr[j];
    }
  }
  cerr << arr[2] << '\n';
  for (int i = 0; i < 60; ++i) {
    cerr << arr[pw[i]] << " \n"[i == 60 - 1];
  }
  for (int i = 0; i < 30; ++i) cerr << arr[s + i] << " \n"[i == 30 - 1];
  for (int i = 0; i < 30; ++i) cerr << arr[t + i] << " \n"[i == 30 - 1];
}

