#include<bits/stdc++.h>
using namespace std;
const int up=32;
const int P0=999999999;
int P2[up+5];
int tot=2;
struct info
{
	char ch;
	int x,y,z;
	info(char a=0,int b=0,int c=0,int d=0):ch(a),x(b),y(c),z(d){}
};
vector<info>A;
inline int smaller(int x,int y)
{
	A.push_back(info('<',x,y,++tot));
	return tot;
}
inline int add(int x,int y)
{
	A.push_back(info('+',x,y,++tot));
	return tot;
}
void init()
{
	int x=add(0,1);
	P2[0]=smaller(P0,x);
	for(int i=1;i<up;++i)
		P2[i]=add(P2[i-1],P2[i-1]);
}
inline int shift(int x,int y)
{
	for(int i=0;i<y;++i)
		x=add(x,x);
	return x;
}
inline int sub(int x,int y)
{
	int sum=add(P0,P0);
	x=add(x,P2[0]);
	for(int i=up-1;i>=0;--i)
	{
		int z=add(add(sum,y),P2[i]);
		int carry=smaller(z,x);
		sum=add(sum,shift(carry,i));
	}
	return sum;
}
inline int isZero(int x)
{
	return smaller(x,P2[0]);
}
inline int check(int x,int y)
{
	return sub(y,shift(isZero(x),up));
}
int multi(int x,int y)
{
	x=add(x,P2[0]);
	int G=add(P0,P0);
	int z=add(P0,P0);
	for(int i=29;i>=0;--i)
	{
		int carry=smaller(P2[i],x);
		z=add(z,check(carry,shift(y,i)));
		x=sub(x,check(carry,P2[i]));
	}
	return z;
}
int main()
{
//	freopen("a.out","w",stdout);
	ios::sync_with_stdio(false);
	init();
	int x=multi(0,1);
	A.push_back(info('+',x,P0,2));
	cout<<A.size()<<endl;
	for(int i=0;i<A.size();++i)
		cout<<A[i].ch<<" "<<A[i].x<<" "<<A[i].y<<" "<<A[i].z<<endl;
	return 0;
}

