const int N = 200000;
int query = 0;
ll a[N] = {};

vector<char> ops;
vector<int> is, js, ks;

void q(char op, int i, int j, int k) {
  is.emplace_back(i);
  js.emplace_back(j);
  ks.emplace_back(k);
  ++query;
  if (op == '+') {
    ops.emplace_back('+');
    a[k] = a[i] + a[j];
  } else if (op == '<') {
    ops.emplace_back('<');
    a[k] = a[i] < a[j];
  }
}

int main() {
  cin >> a[0] >> a[1];
  const int A_BIT = 30, C_BIT = 60;
  const int A = 0, B = 1, C = 2, ONE = 3, P_BASE = ONE, A_BASE = P_BASE + C_BIT, B_BASE = A_BASE + A_BIT;
  q('+', A, B, ONE);
  q('<', C, ONE, ONE);
  FOR(i, 1, C_BIT) {
    q('+', P_BASE + i, P_BASE + i - 1, P_BASE + i);
    q('+', P_BASE + i, P_BASE + i, P_BASE + i);
  }
  for (int i = A_BIT - 1; i >= 0; --i) {
    REP(j, i) q('+', A_BASE + i, P_BASE + j, A_BASE + i);
    FOR(j, i + 1, A_BIT) q('+', A_BASE + i, A_BASE + j, A_BASE + i);
    q('<', A_BASE + i, A, A_BASE + i);
    REP(_, i) q('+', A_BASE + i, A_BASE + i, A_BASE + i);
  }
  REP(i, A_BIT) q('<', C, A_BASE + i, A_BASE + i);
  for (int i = A_BIT - 1; i >= 0; --i) {
    REP(j, i) q('+', B_BASE + i, P_BASE + j, B_BASE + i);
    FOR(j, i + 1, A_BIT) q('+', B_BASE + i, B_BASE + j, B_BASE + i);
    q('<', B_BASE + i, B, B_BASE + i);
    REP(_, i) q('+', B_BASE + i, B_BASE + i, B_BASE + i);
  }
  REP(i, A_BIT) q('<', C, B_BASE + i, B_BASE + i);
  int tmp = N - 1;
  REP(i, A_BIT) REP(j, A_BIT) {
    q('+', A_BASE + i, B_BASE + j, tmp);
    q('<', ONE, tmp, tmp);
    REP(_, i + j) q('+', tmp, tmp, tmp);
    q('+', C, tmp--, C);
  }
  assert(query <= N && a[0] * a[1] == a[2]);
  cout << query << '\n';
  REP(i, query) cout << ops[i] << ' ' << is[i] << ' ' << js[i] << ' ' << ks[i] << '\n';
  return 0;
}

