    // A[N - 2] = 1
    // A[N - 3] = 0
    // A[N - 4] = 0
    // A[n - 1]: temp

    buildOne(N - 2);
    trace();

    for (int i = L - 1; i >= 0; --i) {
        buildPow2(N - 1, i);
        trace();

        for (int j = L - 1; j > i; --j) {
            askSum(j + 4, N - 1, N - 1);
            trace();
        }

        askSum(0, N - 2, N - 5);
        trace();
        askCompare(N - 1, N - 5, i + 4);
        trace();

        for (int j = 0; j < i; ++j) {
            askSum(i + 4, i + 4, i + 4);
        }

        zeroReset(N - 5);
        zeroReset(N - 1);
        trace();
    }
    trace();

    for (int i = L - 1; i >= 0; --i) {
        buildPow2(N - 1, i);
        trace();

        for (int j = L - 1; j > i; --j) {
            askSum(j + 4 + L, N - 1, N - 1);
            trace();
        }

        askSum(1, N - 2, N - 5);
        trace();
        askCompare(N - 1, N - 5, i + 4 + L);
        trace();

        for (int j = 0; j < i; ++j) {
            askSum(i + 4 + L, i + 4 + L, i + 4 + L);
        }
        trace();

        zeroReset(N - 5);
        zeroReset(N - 1);
        trace();
    }
    trace();

    // a: 4 -> L + 3
    // b: L + 4 -> 2 * L + 3
    // a * b: 2 * L + 4 -> 4 * L + 3

    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < L; ++j) {
            binaryMul(i + 4, j + 4 + L, N - 8);
            for (int t = 0; t < i + j; ++t) {
