template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
struct info {
	char opt;
	int i, j, k;
};
vector <info> ans; int v[MAXN];
void check() {
	read(v[0]), read(v[1]);
	for (auto x : ans) {
		if (x.opt == '<') v[x.i] = v[x.j] < v[x.k];
		else v[x.i] = v[x.j] + v[x.k];
	}
	cerr << v[2] << endl;
}
int a, b, res, p, q, one, zero, cnt;
void inc(int x) {
	ans.push_back((info) {'+', x, x, one});
}
int cmp(int x, int y) {
	ans.push_back((info) {'<', ++cnt, x, y});
	return cnt;
}
void update(int x, int y) {
	ans.push_back((info) {'+', ++cnt, x, y});
	int cur = cnt;
	ans.push_back((info) {'<', ++cnt, one, cur});
	ans.push_back((info) {'+', res, res, cnt});
}
int getone() {
	int x = cnt + 1;
	ans.push_back((info) {'+', ++cnt, a, b});
	ans.push_back((info) {'<', ++cnt, zero, x});
	return cnt;
}
