			update(cmp(p, a), cmp(q, b));
			inc(q);
		}
		inc(p);
	}
	cout << ans.size() << endl;
	for (auto x : ans) printf("%c %d %d %d\n", x.opt, x.j, x.k, x.i);
	//check();
	return 0;
}

