vector<string> output;
void COUT(char c, ll s1, ll s2, ll d) {
	string s; s.push_back(c);
	s += " " + to_string(s1) + " " + to_string(s2) + " " + to_string(d);
	output.push_back(s);
}
void _generate(ll src, ll k) {
	for (ll i = 0; i < k; i++) {
		COUT('+', src, src, src);
	}
}

void _and(ll s1, ll s2, ll d) {
	COUT('+', s1, s2, d);
	COUT('<', _ONE, d, d);
}
void _digit(ll src, ll dest) {
	COUT('<', 0, 0, _BUF1);
	COUT('<', 0, 0, _BUF2);

	for (ll i = 60; i >= 0; i--) {
		ll j = dest + i;
		COUT('+', 2, _LOG + i, _BUF_LOG);
		COUT('+', _BUF2, _BUF_LOG, _BUF1);
		COUT('<', _BUF1, src, _BUF_LOG);
		COUT('<', 2, _BUF_LOG, j);
		_generate(_BUF_LOG, i);
		COUT('+', _BUF2, _BUF_LOG, _BUF2);
	}
}

