int a, b;
constexpr int N = 200000;
std::vector<int> vs(N, 0);

void init() {
    std::cin >> a >> b;
    vs[0] = a, vs[1] = b;
}

void query(char c, int i, int j, int k) {
    std::cout << c << " " << i << " " << j << " " << k << "\n";
    if (c == '+') {
        vs[k] = vs[i] + vs[j];
    } else if (c == '<') {
        vs[k] = (vs[i] < vs[j]);
    }
}

void solve() {
    query('+', 0, 1, 3);  // v[3] = a + b
    query('<', 2, 3, 4);  // v[4] = 1 (if a > 0 or b > 0)

    for (int i = 0; i < 20; ++i) {
        // v[5] = bcnt
        query('<', 5, 1, 6);  // v[6] = bcnt < b (bflag)

        // v[7] = acnt
        query('+', 100, 100, 7);  // acnt = 0

        for (int j = 0; j < 20; ++j) {
            query('<', 7, 0, 8);  // v[8] = acnt < a (aflag)

            query('+', 6, 8, 9);   // v[9] = aflag + bflag
