int multiply_by_p2(int x, int h){
    int c = x;
    for(int i = 0 ; i < h ; i++){
        ans.push_back({0, c, c, m++});
        c = m - 1;
    }
    return m - 1;
}
int multiply_bits(int a, int b){
    ans.push_back({0, a, b, m++});
    ans.push_back({1, p2[0], m - 1, m});
    m++;
    return m - 1;
}
int less_than_or_equal(int x, int y){
    int c = m;
    ans.push_back({0, p2[0], y, m++});
    ans.push_back({1, x, c, m++});
    return m - 1;
}
vector <int> get(int f){
