vector<int> PW2,v;
int cnt;
int pw2eq(int p,int k){
	for(int i=1;i<=k;i++)q.emplace_back('+',p,p,p);
	return p;
}
int Less(int p1,int p2){
	q.emplace_back('<',p1,p2,++cnt);
	return cnt;
}
int Plus(int p1,int p2){
	q.emplace_back('+',p1,p2,++cnt);
	return cnt;
