int Minus(int p1,int p2){
	p1=Plus(p1,PW2[0]);
	int ret=maxn;
	for(int i=maxlg-1;i>=0;i--){
		int b=Less(Plus(p2,PW2[i]),p1),c=pw2eq(b,i);
		p2=Plus(p2,c);
		ret=Plus(ret,c);
	}
	return ret;
}
int ifelse(int b,int p){ //b?p:0 => p-(b<<30)
	return Minus(p,pw2eq(Less(b,PW2[0]),30));
}
void solve(int x,vector<int> &v){
	x=Plus(x,PW2[0]);
	for(int i=maxlg-1;i>=0;i--){
		int b=Less(PW2[i],x),c=ifelse(b,PW2[i]);
		x=Minus(x,c);
		v.push_back(b);
	}
	reverse(v.begin(),v.end());
}
