ull frac[N_MAX * 10], invf[N_MAX * 10];
void f_init (sll n, sll m) {
	frac[0] = 1;
	for (sll i = 1; i <= n; i++) {
		frac[i] = frac[i - 1] * i % m;
	}

	invf[n] = divide(1, frac[n], m);
	for (sll i = n - 1; i >= 0; i--) {
		invf[i] = invf[i + 1] * (i + 1) % m;
	}
}
ull ncr (sll n, sll r, ull m) {
	if (n < 0 || r < 0 || n < r) return 0;
	return frac[n] * (invf[r] * invf[n - r] % m) % m;
}

