	}
}
ull find (ull x) {
	if (parent[x] == x) return x;
	return parent[x] = find(parent[x]);
}
bool unite (ull v, ull u) {
	v = find(v);
	u = find(u);



	if (v == u) return false;

	if (size[v] < size[u]) {
		ull tmp = v;
		v = u;
		u = tmp;
	}
	size[v] += size[u];
	parent[u] = v;
	return true;
}

