	leq(0, 0, ret);

	sll i, j;
	sll vv = 16;

	leq(0, 0, mem + vv * 2);
	for (i = 0; i < vv; i++) {
		leq(mem + vv * 2, x, mem + i);
		leq(mem + vv * 2, y, mem + vv + i);

		plus(mem + vv * 2, 3, mem + vv * 2);
	}
	for (i = mem; i < mem + vv; i++) {
		for (j = mem + vv; j < mem + vv * 2; j++) {
			plus(i, j, mem + 33);
			leq(3, mem + 33, mem + 32);
			plus(mem + 32, ret, ret);
		}
	}
}

void func (sll x, sll y, sll ret, sll bits, sll mem) {
	if (bits == 4) {
		stupid4(x, y, ret, mem);
		return;
	}
	sll i;

	leq(0, 0, ret); // a[ret] = 0;
	for (i = 0; i < bits / 2; i++) {
		plus(ret, ret, ret); // a[ret] *= 2;
		plus(ret, 3, ret); // a[ret] += 1;
	}
	// a[ret] == 2^(bits/2)-1

	mem += 10;
	leq(0, 0, mem - 1);
	leq(0, 0, mem - 2);
	leq(0, 0, mem - 3);
	leq(0, 0, mem - 4);
	leq(0, 0, mem - 5);

	leq(0, 0, mem); // a[mem] = 0;
	for (i = 1; i < (1LL << (bits / 2)); i++) {
		plus(mem, ret, mem);

		leq(mem, x, mem + i); // a[mem+i] = (a[x] >= i * 2^(bits/2))
		plus(mem + i, mem - 1, mem - 1);

		leq(mem, y, mem + i); // a[mem+i] = (a[y] >= i * 2^(bits/2))
		plus(mem + i, mem - 2, mem - 2);

		plus(mem, 3, mem);
	}
	// a[mem - 2] = a[y] / 2^(bits/2)

	if (bits >= 15) {

	// fprintf(stderr, "%lld+%lld **\n", a[mem - 1], a[2]);
	plus(mem - 1, 2, mem); // a[mem] = a[mem - 1] = a[x] / 2^(bits/2)
	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem); // a[mem] *= 2;
	}
	plus(2, 2, mem + 1); // a[mem+1] = 0
	for (i = 0; i < bits / 4; i++) {
		plus(mem + 1, mem + 1, mem + 1); // a[mem+1] *= 2;
		plus(mem + 1, 3, mem + 1); // a[mem+1] += 1;
	}
	// fprintf(stderr, "%lld stasrt\n", a[mem]);
	for (i = 1; i < (1LL << (bits / 4)); i++) {
		plus(mem, mem + 1, mem);
		leq(mem, x, mem + 2); // a[mem+2] = (a[x] % 2^(bits/4)) >= i
		plus(mem + 2, mem - 3, mem - 3);
		plus(mem, 3, mem);
	}
	for (i = 0; i < bits / 4; i++) {
		plus(mem - 3, mem - 3, mem - 3);
	}
	plus(mem - 1, 2, mem); // a[mem] = a[mem - 1] = a[x] / 2^(bits/2)
	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem); // a[mem] *= 2;
	}
	plus(mem, mem - 3, mem);
	for (i = 1; i < (1LL << (bits / 4)); i++) {
		leq(mem, x, mem + 2); // a[mem+2] = (a[x] % 2^(bits/4)) >= i
		plus(mem + 2, mem - 3, mem - 3);
		plus(mem, 3, mem);
	}
	// a[mem - 3] = a[x] % 2^(bits/2)

} else {

	// fprintf(stderr, "%lld+%lld **\n", a[mem - 1], a[2]);
	plus(mem - 1, 2, mem); // a[mem] = a[mem - 1] = a[x] / 2^(bits/2)
	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem); // a[mem] *= 2;
	}
	// fprintf(stderr, "%lld stasrt\n", a[mem]);
	for (i = 1; i < (1LL << (bits / 2)); i++) {
		leq(mem, x, mem + i); // a[mem+i] = (a[x] % 2^(bits/2)) >= i
		plus(mem + i, mem - 3, mem - 3);
		plus(mem, 3, mem);
	}
	// a[mem - 3] = a[x] % 2^(bits/2)

}


	plus(mem - 2, 2, mem); // a[mem] = a[mem - 2] = a[y] / 2^(bits/2)
	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem); // a[mem] *= 2;
	}
	for (i = 1; i < (1LL << (bits / 2)); i++) {
		leq(mem, y, mem + i); // a[mem+i] = (a[y] % 2^(bits/2)) >= i
		plus(mem + i, mem - 4, mem - 4);
		plus(mem, 3, mem);
	}
	// a[mem - 4] = a[y] % 2^(bits/2)

	fprintf(stderr, "%lld, %lld, %lld, %lld\n", a[mem - 1], a[mem - 2], a[mem - 3], a[mem - 4]);


	func(mem - 1, mem - 2, mem + 0, (bits + 1) / 2, mem + 1);
	func(mem - 1, mem - 4, mem + 1, (bits + 1) / 2, mem + 2);
	func(mem - 3, mem - 2, mem + 2, (bits + 1) / 2, mem + 3);
	func(mem - 3, mem - 4, mem + 3, (bits + 1) / 2, mem + 4);

	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem);
	}
	plus(mem + 1, mem, mem);
	plus(mem + 2, mem, mem);
	for (i = 0; i < bits / 2; i++) {
		plus(mem, mem, mem);
	}
	plus(mem + 3, mem, ret);

}

