public class Main implements Runnable{

	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Grand Contest 047 E問題
		 * 考察メモ
		 * まず、1を作りたい(後で自由度が上がるので)
		 * a[3] = A + B
		 * a[4] = a[3] > 0
		 * とすると、a[4]はA+B==0でないかぎり1
		 */
		// この時点でa[4] = A + B == 0 ? 1 : 0
		ArrayList<String> ans = new ArrayList<>();
		ans.add(add(0, 1, 3));
		ans.add(compare(4, 3, 4));
		// a[10]..a[20]=0, 1, 2, ..., 10
		// ただしa[4] == 0だと全部0
		for (int i = 11;i <= 20;++ i) {
			ans.add(add(i, 4, i));
			ans.add(add(i, i - 1, i));
		}
		// a[100] .. a[110] = 1, 1, ...1, 0, 0で、合計が丁度Aになる
		for (int i = 100;i <= 110;++ i) {
			ans.add(compare(i - 90, 0, i));
		}
		// a[200] .. a[210] = 1, 1, ...1, 0, 0で、合計が丁度Bになる
		for (int i = 200;i <= 210;++ i) {
			ans.add(compare(i - 190, 0, i));
		}
		// a[300] .. a[420] は丁度A*Bヶ所が2になるような行列
		for (int i = 0;i <= 10;++ i) {
			for (int j = 0;j <= 10;++ j) {
				ans.add(add(i + 100, j + 200, 300 + i * 11 + j));
			}
		}
		// a[2]は、a[300]..a[420]から値が2(つまり1より大きい)だけ加算したい
		// a[5]を一時領域で比較に使い、それを加算する
		for (int i = 0;i < pow(11, 2);++ i) {
			ans.add(compare(4, i + 300, 5));
			ans.add(add(2, 5, 2));
		}
		io.println(ans.size());
		io.println(ans, "\n");
	}

	public String add(int i, int j, int k) {
		return "+ "+ i + " " + j + " " + k;
	}
	public String compare(int i, int j, int k) {
		return "< " + i + " " + j + " " + k;
	}

	/** デバッグ用コードのお供に */
	private static boolean DEBUG = false;
	/** 確保するメモリの大きさ(単位: MB)*/
	private static final long MEMORY = 64;
	private final FastIO io;
	private final String[] args;

	public static void main(String[] args) {
	        Thread.setDefaultUncaughtExceptionHandler((t, e) -> {e.printStackTrace(); System.exit(1);});
	        new Thread(null, new Main(args), "", MEMORY * 1048576).start();
	}

	public Main(String[] args) {
		this(new FastIO(), args);
	}

	public Main(FastIO io, String... args) {
		this.io = io;
		this.args = args;
		if (DEBUG) io.setAutoFlush(true);
	}

	@Override
	public void run() {
		try {
			solve(io, args);
		} catch (Throwable e) {
			throw e;
		} finally {
			io.flush();
		}
	}

