                }

                for (int i = 0; i <= 10; i++)
                {
                    operations.Enqueue($"< {mul + 10} 1 {i + 50}");
                }

                for (int add = 0; add <= 10; add++)
                {
                    operations.Enqueue($"+ {add + 30} {add + 50} {add + 30}");
                }

                for (int i = 0; i <= 10; i++)
                {
                    operations.Enqueue($"< 11 {i + 30} {i + 30}");
                }

                for (int i = 0; i <= 10; i++)
                {
