internal partial class Solver {
    struct Operation {
        public char Op;
        public int i, j, k;
        public Operation(char op, int i, int j, int k) {
            this.Op = op;
            this.i = i;
            this.j = j;
            this.k = k;
        }

        object Dump() => new { Op, i, j, k };
    }
    public void Run() {
        var ans = new List<Operation>();
        var digitOffset = 100;
        var offSetA = 400;
        var offSetB = 500;
        var register = 1000;
        for (int i = 0; i <= 100; i++) {
            ans.Add(new Operation('<', i + digitOffset, 0, i + digitOffset));
        }
        ans.Add(new Operation('+', digitOffset, 0, 0));
        for (int i = 1; i <= 100; i++) {
            ans.Add(new Operation('+', i + digitOffset, i + digitOffset - 1, i + digitOffset));
        }
        for (int i = 0; i <= 100; i++) {
            ans.Add(new Operation('<', i + digitOffset, 0, i + offSetA));
        }
        for (int i = 0; i <= 100; i++) {
            //ans.Add(new Operation('<', i + digitOffset, 1, i + offSetB));
            ans.Add(new Operation('<', 1, i + digitOffset, i + offSetB));
        }
        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j <= 100; j++) {
                ans.Add(new Operation('<', j + offSetB, i + offSetA, register));
                ans.Add(new Operation('+', register, 2, 2));
            }
        }

        cout.WriteLine(ans.Count);
        foreach (var o in ans) {
            cout.WriteLine("{0} {1} {2} {3}", o.Op, o.i, o.j, o.k);
