    public static string Solve(int a, int b)
    {
        List<string> seq = new List<string>();
        //gen 1
        var xptr = 0;
        var yptr = 1;
        var resptr = 2;
        var zeroPtr = 199999;
        var onePtr = 3;

        int[] arr = new int[200000];
        arr[xptr] = a;
        arr[yptr] = b;

        void CompAssign(int a, int b, int res) { arr[res] = arr[a] < arr[b] ? 1 : 0; seq.Add($"< {a} {b} {res}"); }
        void AddAssign(int a, int b, int res) { arr[res] = arr[a] + arr[b]; seq.Add($"+ {a} {b} {res}"); }
        void Add(int ptr, int adder) => AddAssign(ptr, adder, ptr);
        void Incr(int ptr) => Add(ptr, onePtr);
        void SetZero(int ptr) => CompAssign(zeroPtr, zeroPtr, ptr);
        void SetOne(int ptr) => CompAssign(zeroPtr, xptr, ptr);

        SetOne(onePtr);
        var flg1 = 4;
        var flg2 = 5;
        int iptr = 100;
        int jptr = 101;
        for (int i = 1; i <= 10; i++)
