            SetZero(jptr);
            for (int j = 1; j <= 10; j++)
            {
                CompAssign(jptr, yptr, flg2);
                AddAssign(flg1, flg2, flg1);
                CompAssign(onePtr, flg1, flg1);
                AddAssign(resptr, flg1, resptr);
                Incr(jptr);
            }
            Incr(iptr);
        }
