class Myon

{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }
    static Scanner cin;


    List<string> ans;


    void add2n(int p, int t, int n, bool AddFlag)
    {
        //a[9999] = 0;
        //a[10000] = 1
        ans.Add("> 0 0 10000");
        ans.Add("+ 10 10000 10000");
        for (int i = 0; i < n; i++)
        {
            ans.Add($"{10000 + i} {10000 + i} {10000 + i + 1}");
        }
        if (AddFlag) ans.Add($"+ {t} {10000 + n} {t}");
        else ans.Add($"+ 9999 {10000 + n} {t}");
    }

    void calc()
    {
        ans = new List<string>();

        //a[3]をめちゃめちゃ大きくする
        ans.Add("+ 0 3 3");
        ans.Add("+ 0 3 3");
        ans.Add("+ 1 3 3");
        ans.Add("+ 1 3 3");

        //a[10] == 1
        ans.Add("< 2 3 10");
        //a[11] == 1
        ans.Add("+ 11 10 11");

        //a[100] = 1;
        ans.Add("+ 10 100 100");

        //a[4] = A+1
        ans.Add("+ 0 10 4");
        //a[5] = B+1
        ans.Add("+ 1 10 5");

        //a[1{00,n}] = 2^n;
        for (int i = 1; i <= 30; i++)
        {
            ans.Add(string.Format($"+ {100 + i - 1} {100 + i - 1} {100 + i}"));
        }

        ans.Add("+ 9999 9999 1000");
        ans.Add("+ 9999 9999 1001");

        //a[2{00,n}] = 2^n をbitに含むかどうか判定
        for (int i = 30 - 1; i >= 0; i--)
        {
            ans.Add($"+ 1000 {100 + i} 1001");
            ans.Add($"< 1001 {4} {200 + i}");
            add2n(200 + i, 1000, i, true);
        }

        //a[1000] = 確定num
        //a[1001] = お試しnum


        ans.Add("+ 9999 9999 1000");
        ans.Add("+ 9999 9999 1001");

        //a[3{00,n}] = 2^n をbitに含むかどうか判定
        for (int i = 30 - 1; i >= 0; i--)
        {
            ans.Add($"+ 1000 {100 + i} 1001");
            ans.Add($"< 1001 {5} {300 + i}");
            add2n(300 + i, 1000, i, true);
        }


        //a[1ij] Aがiより大きい判定+Bがjより大きい判定
        for (int i = 0; i < 30; i++)
        {
            for (int j = 0; j < 30; j++)
            {
                ans.Add(string.Format($"+ {200 + i} {300 + j} {1000 + i * 30 + j}"));
            }
        }

        for (int i = 0; i < 30; i++)
        {
            for (int j = 0; j < 30; j++)
            {
                ans.Add(string.Format($"< {11} {1000 + i * 30 + j} {1000 + i * 30 + j}"));
                add2n(1000 + i * 30 + j, 1000 + i * 30 + j, i + j, false);
            }
        }

        //全部足す
        for (int i = 0; i < 30; i++)
        {
            for (int j = 0; j < 30; j++)
            {
                ans.Add(string.Format($"+ {2} {1000 + i * 30 + j} {2}"));
            }
        }

        Console.WriteLine(ans.Count);
        foreach (var s in ans)
        {
            Console.WriteLine(s);
        }
    }
}


class Scanner
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int nextInt()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextInt() + add;
        }
        return Array;
    }

    public long nextLong()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextLong() + add;
        }
        return Array;
    }

    public double nextDouble()
    {
        return double.Parse(next());
    }


    public double[] ArrayDouble(int N, double add = 0)
    {
        double[] Array = new double[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = nextDouble() + add;
        }
        return Array;
    }
}

