class CodeGen:
    codes = []
    cnt = 100

    def __init__(self, A, B):
        self.A = A
        self.B = B    
        self.C1 = self.one()
        self.C2 = self.pow2(self.C1, 1)
        self.C3 = self.pow2(self.C1, 2)
        self.C4 = self.pow2(self.C1, 3)

        self.POW2 = [self.C1]
        for i in range(32):
            self.POW2.append(self.pow2(self.C1, i + 1))

    def allocate(self):
        self.cnt += 1
        return self.cnt - 1

    def plus(self, x, y):
        l = self.allocate()
        self.codes.append(f"+ {x} {y} {l}")
        return l

    def gt(self, x, y):
        l = self.allocate()
        self.codes.append(f"< {x} {y} {l}")
        return l

    def ge(self, x, y):
        return self.gt(x, self.plus(y, self.C1))

    def pow2(self, x, n):
        t = x
        for _ in range(n):
            t = self.plus(t, t)
        return t

    def one(self):
        return self.gt(self.allocate(), self.plus(self.A, self.B))

    def bits(self, x, n):
        result = []

        t = self.allocate()
        for i in range(n - 1, -1, -1):
            bit = self.ge(self.plus(self.POW2[i], t), x)
            result.append(bit)
            t = self.plus(t, self.pow2(bit, i))
        return result

    def mult(self, x, y):
        return self.gt(self.C1, self.plus(x, y))

    def show(self, ans):
        t = self.allocate()
        self.codes.append(f"+ {ans} {t} 2")

        print(len(self.codes))
        for c in self.codes:
            print(c)

    def pluss(self, xs):
        if len(xs) == 1:
            return xs[0]
        return self.plus(xs[0], self.pluss(xs[1:]))

class Eval(CodeGen):
    def __init__(self, A, B):
        super().__init__(A, B)

    def allocate(self):
        return 0

    def plus(self, x, y):
        return x + y

    def gt(self, x, y):
        if x < y:
            return 1
        return 0

    def show(self, ans):
        print(ans)


