#![allow(unused_imports)]
#![allow(bare_trait_objects)] // for compatibility with 1.15.1
use std::cmp::Ordering::{self, Greater, Less};
use std::cmp::{max, min};
use std::collections::{BTreeMap, BTreeSet, BinaryHeap, HashMap, HashSet, VecDeque};
use std::error::Error;
use std::io::{self, BufReader, BufWriter, Read, Write};
use text_scanner::{scan, scan_iter, scanln, scanln_iter};
use utils::adj4_iter;

enum Ops {
    Add(usize, usize, usize),
    Lt(usize, usize, usize),
}

struct Solver {
    regs: HashMap<String, usize>,
    regs_rev: HashMap<usize, String>,
    ops: Vec<Ops>,
}

impl Solver {
    fn new() -> Solver {
        let mut s = Solver {
            regs: HashMap::new(),
            regs_rev: HashMap::new(),
            ops: Vec::new(),
        };
        s.reg("a"); // 0
        s.reg("b"); // 1
        s.reg("ans"); // 2
        s.reg("zero");
        s.add("s", "a", "b");
        s.lt("one", "zero", "s");
        s
    }
    fn reg(&mut self, name: &str) -> usize {
        if let Some(x) = self.regs.get(name) {
            return *x;
        }
        let new_id = self.regs.len();
        self.regs.insert(name.to_string(), new_id);
        self.regs_rev.insert(new_id, name.to_string());
        new_id
    }

    // d = f1 + f2
    fn add(&mut self, d: &str, f1: &str, f2: &str) {
        let f1 = self.reg(f1);
        let f2 = self.reg(f2);
        let d = self.reg(d);
        self.ops.push(Ops::Add(f1, f2, d));
    }

    // d += f
    fn inc(&mut self, d: &str, f: &str) {
        self.add(d, d, f);
    }

    fn inc_one(&mut self, d: &str) {
        self.inc(d, "one")
    }

    // d = 0
    fn set_zero(&mut self, d: &str) {
        self.lt(d, "zero", "zero")
    }

    // d = f
    fn set(&mut self, d: &str, f: &str) {
        self.set_zero(d);
        self.inc(d, f);
    }

    // d = f1 < f2
    fn lt(&mut self, d: &str, f1: &str, f2: &str) {
        let f1 = self.reg(f1);
        let f2 = self.reg(f2);
        let d = self.reg(d);
        self.ops.push(Ops::Lt(f1, f2, d));
    }

    fn name(&self, x: usize) -> &str {
        &self.regs_rev[&x]
    }

    fn simulate(&self, a: i64, b: i64) -> i64 {
        let n = 200000;
        let mut v = vec![0i64; n];
        v[0] = a;
        v[1] = b;
        for o in &self.ops {
            match o {
                &Ops::Add(x, y, z) => {
                    eprintln!(
                        "{} ({}) = {} ({}) + {} ({})",
                        self.name(z),
                        v[z],
                        self.name(x),
                        v[x],
                        self.name(y),
                        v[y]
                    );
                    v[z] = v[x] + v[y];
                }
                &Ops::Lt(x, y, z) => {
                    eprintln!(
                        "{} ({}) = {} ({}) < {} ({})",
