macro_rules! add {
    ($x: expr, $a: expr, $b: expr) => {
        println!("+ {} {} {}", $x, $a, $b)
    };
}

macro_rules! lt {
    ($x: expr, $a: expr, $b: expr) => {
        println!("< {} {} {}", $x, $a, $b)
    };
}

fn main() {
    let a = 0;
    let b = 1;
    let ans = 2;
    let one = 3;
    let i = 4;
    let j = 5;
    let q = 6;
    let r = 7;
    let zero = 8;

    println!("513");
    add!(one, a, b);
    lt!(one, zero, one);
    add!(i, zero, zero);
    for _ in 0..10 {
        add!(j, zero, zero);
        for _ in 0..10 {
            lt!(q, i, a);
            lt!(r, j, b);
            add!(q, q, r);
            lt!(q, one, q);
            add!(ans, ans, q);
        }
    }
}

const N: usize = 2e5 as usize;
const BIT: usize = 32;

fn main() {
    let mut s: Vec<String> = vec![];

    let mut memory = vec![0; N];
    memory[0] = 1;
    s.push_str("+ 0 1 3");
    s.push_str("+ 3 3 3");
    s.push_str("< 0 3 3");

    apply(&s, &mut memory);
    assert_eq!(memory[2], 0);
    assert_eq!(memory[3], 1);

    let prev = s.len();
    for i in 1..BIT {
        let k = i + 3;
        s.push(format!("+ {} {} {}", k - 1, k - 1, k));
    }
    apply(&s[prev..], &mut memory);
    assert_eq!(memory[4], 2);
    assert_eq!(memory[BIT + 2], 1u128 << (BIT - 1));

    for &(ab, offset) in [(0, BIT + 3), (1, BIT * 2 + 3)].iter() {
        let t1 = N - 1;
        let t2 = N - 2;
        let sum = N - 3;
        s.push(format!("< 3 2 {}", sum));
        for i in (0..BIT).rev() {
            let one = 3;
            let j = i + 3; // 2**i
            let pos = i + offset;
            s.push(format!("+ {} {} {}", ab, one, t1)); // t1 = a + 1
            s.push(format!("+ {} {} {}", sum, j, t2)); // t2 = sum + 2**i
            s.push(format!("< {} {} {}", t2, t1, pos)); // pos = (2**i < a-sum)

            for _ in 0..i {
                s.push(format!("+ {} {} {}", pos, pos, pos));
            }
            s.push(format!("+ {} {} {}", sum, pos, sum)); // sum += pos
            s.push(format!("< {} {} {}", t2, t1, pos)); // pos = (2**i < a-sum)
        }
    }

    // a:  74 ... 144
    // b: 145 ... 215

    for i in 0..BIT {
        for j in 0..BIT {
            let tmp = N - 1;
            let ans = 2;
            let bi = i + BIT + 3;
            let bj = j + BIT * 2 + 3;
            let one = 3;
            s.push(format!("+ {} {} {}", bi, bj, tmp)); // tmp = bit[i] + bit[j]
            s.push(format!("< {} {} {}", one, tmp, tmp)); // tmp = bit[i] & bit[j]

            for _ in 0..(i + j) {
                s.push(format!("+ {} {} {}", tmp, tmp, tmp));
            }
            s.push(format!("+ {} {} {}", ans, tmp, ans));
        }
    }

    validate(&s, 3, 4);
    println!("{}", s.len());
    for s in s.iter() {
        println!("{}", s);
    }
}

trait PushStr {
    fn push_str(&mut self, s: &str);
}

impl PushStr for Vec<String> {
    fn push_str(&mut self, s: &str) {
        self.push(s.to_string());
    }
}

fn apply(s: &[String], memory: &mut [u128]) {
    for s in s.iter() {
        let s = s.split(" ").collect::<Vec<_>>();
        let i = s[1].parse::<usize>().unwrap();
        let j = s[2].parse::<usize>().unwrap();
        let k = s[3].parse::<usize>().unwrap();
        match s[0] {
            "+" => {
                memory[k] = memory[i] + memory[j];
            }
            "<" => {
                if memory[i] < memory[j] {
                    memory[k] = 1;
                } else {
                    memory[k] = 0;
                }
            }
            _ => unreachable!(),
        }
    }
}

fn validate(s: &[String], a: u128, b: u128) {
    let mut memory = vec![0; N];
    memory[0] = a;
    memory[1] = b;

    apply(s, &mut memory);

    assert_eq!(memory[2], a * b, "{:?}", &memory[0..100]);
}

