pub fn solve<R: BufRead>(mut reader: StdinReader<R>) {
    let mut v = Vec::new();
    // 0 0 の場合は何をやっても0なので大丈夫

    //1をつくる
    v.push(format!("< 2 0 5"));
    v.push(format!("< 2 1 6"));
    v.push(format!("< 5 6 7"));
    v.push(format!("< 6 5 8"));
    v.push(format!("+ 5 7 5"));
    v.push(format!("+ 5 8 5")); //5が1になる

    for i in 0..10 {
        v.push(format!("< 3 0 {}", 10 + i));
        v.push(format!("+ 3 5 3"));
    }
    for i in 0..10 {
        v.push(format!("< 4 1 {}", 20 + i));
        v.push(format!("+ 4 5 4"))
    }

    for i in 0..10 {
        for j in 0..10 {
            v.push(format!("+ {} {} 7", 10 + i, 20 + j));
